--------------------------------------------------------------------------------
-- MelloUI - Voice Over
--
-- Reads NPC dialog aloud with the client's built in text-to-speech: gossip
-- greetings, quest offers, progress and turn-in text. Speech keeps playing
-- after the window is closed, so you can accept a quest and walk off while the
-- NPC is still talking.
--
-- Voices come from the operating system (the same ones the chat text-to-speech
-- accessibility feature uses). The NPC's race and gender are looked up in
-- Media\NPCVoiceData.lua (generated by Tools\extract_npc_voices.py) and
-- Media\NPCVoiceOverrides.lua (hand written). Each race has a pitch and speed
-- profile so goblins chatter and ogres rumble, and any race group can be given
-- its own voice. NPCs missing from the data fall back to the gender voices.
--
-- If a VoiceOver data pack (AI_VoiceOverData_Vanilla) is installed, its
-- recorded lines are played instead of text-to-speech whenever one exists.
--
-- Commands: /vo stop, /vo pause, /vo skip, /vo read, /vo test, /vo voices, /vo npc,
-- /vo packs (what loaded, the last lookups), /vo lines, /vo reset
--------------------------------------------------------------------------------

local ADDON_NAME, ns = ...
local MelloUI = ns.MelloUI
local Perf = MelloUI.Perf:Scope("VoiceOver")
local C_Timer = Perf.C_Timer

local AUTO_VOICE = -1

-- Filled from C_VoiceChat.GetTtsVoices(); the config dropdowns read this table
-- lazily, so refilling it in place is enough to refresh the list.
local VOICE_VALUES = { { value = AUTO_VOICE, label = "Automatic (by gender)" } }

--------------------------------------------------------------------------------
-- Race profiles
--
-- pitch and rate are offsets in the speech engine's -10..10 units. They are
-- scaled by the Profile Strength setting, and rate is added to the base speed.
--------------------------------------------------------------------------------

