--------------------------------------------------------------------------------
-- Helpers
--------------------------------------------------------------------------------

-- secret-safe reads, one set for the addon (MelloUI.Safe, Core.lua)
local IsSecret = MelloUI.Safe.IsSecret

local function IsPlainNumber(v)
	return type(v) == "number" and not IsSecret(v)
end

local function HasTTS()
	return C_VoiceChat and C_VoiceChat.SpeakText and C_VoiceChat.GetTtsVoices
end

local function Clamp(v, lo, hi)
	if v < lo then return lo end
	if v > hi then return hi end
	return v
end

local FEMALE_HINTS = { "zira", "hazel", "susan", "heera", "catherine", "linda", "eva", "female", "aria", "jenny", "sonia", "natasha", "libby", "sara", "hedda", "helena", "julie", "irina", "hortense", "elsa", "maria", "hoda", "ayumi", "haruka", "huihui", "yaoyao", "tracy", "michelle", "emma", "ana", "clara", "sofia", "olivia", "amber", "ashley", "cora", "elizabeth", "jane", "monica", "nancy", "zoe" }

local function LooksFemale(name)
	name = (name or ""):lower()
	for _, hint in ipairs(FEMALE_HINTS) do
		if name:find(hint, 1, true) then
			return true
		end
	end
	return false
end

local voices = {}          -- list of { voiceID, name }
local voiceByID = {}       -- [voiceID] = name

local function RefreshVoices()
	wipe(voices)
	wipe(voiceByID)
	for i = #VOICE_VALUES, 2, -1 do
		VOICE_VALUES[i] = nil
	end
	if not HasTTS() then
		return
	end
	local ok, list = pcall(C_VoiceChat.GetTtsVoices)
	if not ok or type(list) ~= "table" then
		return
	end
	for _, voice in ipairs(list) do
		if IsPlainNumber(voice.voiceID) and type(voice.name) == "string" then
			voices[#voices + 1] = { voiceID = voice.voiceID, name = voice.name }
			voiceByID[voice.voiceID] = voice.name
			VOICE_VALUES[#VOICE_VALUES + 1] = { value = voice.voiceID, label = voice.name }
		end
	end
end

local function AutoVoice(female)
	if #voices == 0 then
		return nil
	end
	for _, voice in ipairs(voices) do
		if LooksFemale(voice.name) == female then
			return voice.voiceID
		end
	end
	return voices[1].voiceID
end

local function ChosenVoice(key)
	local chosen = M.db[key]
	if chosen ~= nil and chosen ~= AUTO_VOICE and voiceByID[chosen] then
		return chosen
	end
	return nil
end

local function PickVoice(race, female)
	if race then
		local group = GroupForRace(race)
		local voice = ChosenVoice("voice_" .. group.key)
		if voice then
			return voice
		end
	end
	return ChosenVoice(female and "femaleVoice" or "maleVoice") or AutoVoice(female)
end

--------------------------------------------------------------------------------
-- NPC lookup
--------------------------------------------------------------------------------

local npcLookup = nil   -- [npcID] = { race = string, gender = "m" | "f" | "n" }

local function BuildLookup()
	npcLookup = {}
	if type(MelloUI_NPCVoiceData) == "table" then
		for key, ids in pairs(MelloUI_NPCVoiceData) do
			local race, gender = tostring(key):match("^(%a+)_(%a)$")
			if race and type(ids) == "string" then
				local info = { race = race, gender = gender }
				for id in ids:gmatch("%d+") do
					npcLookup[tonumber(id)] = info
				end
			end
		end
	end
	if type(MelloUI_NPCVoiceOverrides) == "table" then
		for key, entry in pairs(MelloUI_NPCVoiceOverrides) do
			local id = tonumber(key)
			if id and type(entry) == "table" then
				local race = entry.race or entry[1]
				local gender = entry.gender or entry[2]
				if type(race) == "string" then
					npcLookup[id] = { race = race:lower(), gender = type(gender) == "string" and gender:sub(1, 1):lower() or "n", override = true }
				end
			end
		end
	end
end

local function NPCIDFromUnit(unit)
	local ok, guid = pcall(UnitGUID, unit)
	if not ok or type(guid) ~= "string" or IsSecret(guid) then
		return nil
	end
	local id = guid:match("^Creature%-%d+%-%d+%-%d+%-%d+%-(%d+)")
	return id and tonumber(id) or nil
end

local function UnitFemale(unit)
	local ok, sex = pcall(UnitSex, unit)
	if ok and IsPlainNumber(sex) then
		return sex == 3, true
	end
	return false, false
end

local function UnitPlainName(unit)
	local ok, name = pcall(UnitName, unit)
	if ok and type(name) == "string" and not IsSecret(name) then
		return name
	end
	return nil
end

-- Describe the NPC currently being talked to (or targeted, for /vo commands).
local function DescribeNPC(preferTarget)
	if not npcLookup then
		BuildLookup()
	end
	local units = preferTarget and { "target", "npc", "questnpc" } or { "npc", "questnpc", "target" }
	for _, unit in ipairs(units) do
		local ok, exists = pcall(UnitExists, unit)
		if ok and exists then
			local id = NPCIDFromUnit(unit)
			if id then
				local info = npcLookup[id]
				local female, known = UnitFemale(unit)
				local gender
				if info and info.gender ~= "n" then
					female = info.gender == "f"
					gender = info.gender
				elseif known then
					gender = female and "f" or "m"
				else
					gender = info and info.gender or "n"
				end
				return {
					unit = unit,
					id = id,
					name = UnitPlainName(unit),
					race = info and info.race or nil,
					gender = gender,
					female = female,
					source = info and (info.override and "override" or "data") or "unknown",
				}
			end
		end
	end
	return nil
end

--------------------------------------------------------------------------------
-- Text
--------------------------------------------------------------------------------

-- Strip UI escape sequences so the voice does not read colour codes.
local function CleanText(text)
	if type(text) ~= "string" or IsSecret(text) then
		return text
	end
	text = text:gsub("|c%x%x%x%x%x%x%x%x", "")
	text = text:gsub("|r", "")
	text = text:gsub("|T.-|t", "")
	text = text:gsub("|A.-|a", "")
	text = text:gsub("|H.-|h(.-)|h", "%1")
	text = text:gsub("|n", " ")
	text = text:gsub("%s+", " ")
	text = text:gsub("^%s+", ""):gsub("%s+$", "")
	return text
end

local function EscapeXML(text)
	return (text:gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
end

-- Pitch / rate for an NPC according to its race profile and the settings.
local function VoiceShape(race)
	local base = tonumber(M.db.rate) or 0
	if not M.db.raceProfiles or not race then
		return 0, Clamp(base, -10, 10), DEFAULT_PROFILE
	end
	local profile = RACE_PROFILES[race] or DEFAULT_PROFILE
	local strength = tonumber(M.db.profileStrength) or 1
	local pitch = Clamp(math.floor(profile.pitch * strength + 0.5), -10, 10)
	local rate = Clamp(base + math.floor(profile.rate * strength + 0.5), -10, 10)
	return pitch, rate, profile
end

--------------------------------------------------------------------------------
-- Sound packs
--
-- The VoiceOver addon's data packs (AI_VoiceOverData_Vanilla and friends) are
-- load-on-demand addons holding one MP3 per quest line and greeting plus Lua
-- lookup tables. They are loaded here without the VoiceOver player and read
-- directly: quest lines by quest ID, greetings by NPC and text.
--------------------------------------------------------------------------------

local packs = {}            -- { name = addon, data = table, priority = number }
local packsLoaded = false
local packErrors = {}
local lookupTrace = {}      -- last few lookup results, for /vo packs
local MAX_TRACE = 8

local function Trace(fmt, ...)
	table.insert(lookupTrace, 1, string.format(fmt, ...))
	lookupTrace[MAX_TRACE + 1] = nil
end
local activeHandle = nil    -- sound handle of the file being played

local function AddOnAPI(name)
	return (C_AddOns and C_AddOns[name]) or _G[name]
end

local function PlainNumber(v)
	return IsPlainNumber(v) and v or nil
end

local function LoadSoundPacks()
	if packsLoaded then
		return
	end
	packsLoaded = true
	local GetNumAddOns, GetAddOnInfo, GetAddOnMetadata = AddOnAPI("GetNumAddOns"), AddOnAPI("GetAddOnInfo"), AddOnAPI("GetAddOnMetadata")
	local IsAddOnLoaded, LoadAddOn = AddOnAPI("IsAddOnLoaded"), AddOnAPI("LoadAddOn")
	if not (GetNumAddOns and GetAddOnInfo and GetAddOnMetadata and IsAddOnLoaded and LoadAddOn) then
		return
	end
	for i = 1, GetNumAddOns() do
		local name = GetAddOnInfo(i)
		local ok, version = pcall(GetAddOnMetadata, name, "X-VoiceOver-DataModule-Version")
		if ok and version then
			-- The pack files expect the VoiceOver player's globals to exist.
			if type(_G.VoiceOver) ~= "table" then
				_G.VoiceOver = {}
			end
			if type(_G.VoiceOver.DataModules) ~= "table" then
				_G.VoiceOver.DataModules = { Register = function() end }
			end
			if type(_G[name]) ~= "table" then
				_G[name] = {}
			end
			local loaded, reason = IsAddOnLoaded(name), nil
			if not loaded then
				-- The packs carry an old interface number; allow out of date
				-- addons just for this load and put the settings back after.
				local prevCheck = GetCVar("checkAddonVersion")
				local prevLast = GetCVar("lastAddonVersion")
				pcall(SetCVar, "checkAddonVersion", 0)
				local _, _, _, interface = GetBuildInfo()
				if prevLast ~= nil and interface then
					pcall(SetCVar, "lastAddonVersion", interface)
				end
				local callOk, a, b = pcall(LoadAddOn, name)
				if prevCheck ~= nil then pcall(SetCVar, "checkAddonVersion", prevCheck) end
				if prevLast ~= nil then pcall(SetCVar, "lastAddonVersion", prevLast) end
				if callOk then
					loaded, reason = a, b
				else
					loaded, reason = false, tostring(a)
				end
			end
			local data = _G[name]
			if loaded and type(data) == "table" and type(data.SoundLengthLookupByFileName) == "table" then
				local _, priority = pcall(GetAddOnMetadata, name, "X-VoiceOver-DataModule-Priority")
				packs[#packs + 1] = { name = name, data = data, priority = tonumber(priority) or 0 }
			else
				packErrors[name] = tostring(reason or (loaded and "no lookup tables" or "not loaded"))
			end
		end
	end
	table.sort(packs, function(a, b) return a.priority > b.priority end)
	if #packs > 0 and (IsAddOnLoaded("AI_VoiceOver_Continued") or IsAddOnLoaded("AI_VoiceOver")) then
		MelloUI:Notice("Voice Over: the VoiceOver player addon is also enabled, so lines may play twice. Disable one of them.")
	end
end

-- The pack texts keep the placeholders ($n name, $c class, $r race) that the
-- live text has already filled in. Put the placeholders back, drop case and
-- punctuation, so both sides compare on words alone.
local playerTokens = nil

local function PlayerTokens()
	if playerTokens then
		return playerTokens
	end
	playerTokens = {}
	local function Add(value, placeholder)
		if type(value) == "string" and not IsSecret(value) and value ~= "" then
			playerTokens[#playerTokens + 1] = { value:lower(), placeholder }
		end
	end
	local ok, name = pcall(UnitName, "player")
	if ok then Add(name, "$n") end
	local ok2, class = pcall(UnitClass, "player")
	if ok2 then Add(class, "$c") end
	local ok3, race = pcall(UnitRace, "player")
	if ok3 then Add(race, "$r") end
	return playerTokens
end

local function Normalise(text)
	text = text:lower()
	for _, pair in ipairs(PlayerTokens()) do
		local value, placeholder = pair[1], pair[2]
		text = text:gsub(value:gsub("%p", "%%%0"), placeholder)
	end
	-- $N / $C / $R are the capitalised forms of the same placeholders; $B is
	-- a line break in the pack texts, plain whitespace in the live text.
	text = text:gsub("%$g[^;]*;[^;]*;", " ")
	text = text:gsub("%$b", " ")
	text = text:gsub("[^%w%$%s]", " ")
	return text
end

-- Word overlap between two texts, 0..1 (the matcher the VoiceOver addon uses).
local function Similarity(a, b)
	local tokensA, tokensB = {}, {}
	for token in Normalise(a):gmatch("%S+") do tokensA[token] = true end
	for token in Normalise(b):gmatch("%S+") do tokensB[token] = true end
	local intersection, union = 0, 0
	for token in pairs(tokensA) do
		union = union + 1
		if tokensB[token] then intersection = intersection + 1 end
	end
	for token in pairs(tokensB) do
		if not tokensA[token] then union = union + 1 end
	end
	if union == 0 then return 0 end
	return intersection / union
end

local function BestMatch(query, entries, minimum)
	local exact = entries[query]
	if exact ~= nil then
		return exact, 1
	end
	local bestValue, bestScore = nil, minimum or 0
	for text, value in pairs(entries) do
		local score = Similarity(query, text)
		if score > bestScore then
			bestValue, bestScore = value, score
		end
	end
	return bestValue, bestScore
end

local function PackFile(pack, kind, fileName)
	local lengths = pack.data.SoundLengthLookupByFileName
	local folder = kind == "gossip" and "gossip" or "quests"
	-- Lines whose words depend on the player's gender ($G) exist only as
	-- m- / f- files (213 quest lines of the vanilla pack have no plain file):
	-- the player's own gender first, the plain file, then either gendered
	-- file rather than silence when UnitSex answers nothing on this client.
	local sex = PlainNumber(select(2, pcall(UnitSex, "player")))
	local prefix = sex == 2 and "m-" or (sex == 3 and "f-" or nil)
	if prefix and lengths[prefix .. fileName] then
		fileName = prefix .. fileName
	elseif not lengths[fileName] then
		if lengths["m-" .. fileName] then
			fileName = "m-" .. fileName
		elseif lengths["f-" .. fileName] then
			fileName = "f-" .. fileName
		else
			return nil
		end
	end
	return string.format("Interface\\AddOns\\%s\\generated\\sounds\\%s\\%s.mp3", pack.name, folder, fileName), lengths[fileName], fileName
end

local function FirstWords(text, n)
	local words = {}
	for word in text:gmatch("%S+") do
		words[#words + 1] = word
		if #words >= n then break end
	end
	return table.concat(words, " ")
end

local function LastWords(text, n)
	local words = {}
	for word in text:gmatch("%S+") do
		words[#words + 1] = word
	end
	return table.concat(words, " ", math.max(1, #words - n + 1), #words)
end

local function Unquote(text)
	return (text:gsub('"', "'"))
end

-- Quest ID from the client, or from the packs' title / NPC / text tables
-- when the client reports none.
local function ResolveQuestID(kind, npc, title, text, tablesOnly)
	if GetQuestID and not tablesOnly then
		local ok, id = pcall(GetQuestID)
		id = ok and PlainNumber(id) or nil
		if id and id > 0 then
			return id
		end
	end
	if type(title) ~= "string" or type(text) ~= "string" or IsSecret(text) then
		return nil
	end
	local cleanTitle = Unquote(title)
	local cleanName = Unquote(npc and npc.name or "")
	local cleanText = Unquote(FirstWords(text, 15)) .. " " .. Unquote(LastWords(text, 15))
	for _, pack in ipairs(packs) do
		local lookup = pack.data.QuestIDLookup and pack.data.QuestIDLookup[kind]
		local byTitle = lookup and lookup[cleanTitle]
		if type(byTitle) == "number" then
			return byTitle
		elseif type(byTitle) == "table" then
			local byNPC = byTitle[cleanName]
			if type(byNPC) == "number" then
				return byNPC
			elseif type(byNPC) == "table" then
				local id = BestMatch(cleanText, byNPC, 0.3)
				if id then return id end
			end
		end
	end
	return nil
end

-- Recorded file for a quest line: path, length in seconds.
local function PackQuestLine(kind, npc, title, text, questID)
	questID = questID or ResolveQuestID(kind, npc, title, text)
	if not questID then
		Trace("%s %q: no quest ID from the client or the pack tables", kind, tostring(title))
		return nil
	end
	for _, pack in ipairs(packs) do
		local path, length, name = PackFile(pack, kind, questID .. "-" .. kind)
		if path then
			Trace("%s %q: quest %d, recorded", kind, tostring(title), questID)
			return path, length, name
		end
	end
	-- Forever gave some vanilla quests new IDs (Chief Engineer Scooty 2842 ->
	-- 80133, the Zandalar enchant quests, ...) with the old words: look the
	-- title / NPC / text up in the pack tables and take the old recording
	-- when that names a different quest with a file. A Forever recording
	-- under the new ID (above) always wins.
	local old = ResolveQuestID(kind, npc, title, text, true)
	if old and old ~= questID then
		for _, pack in ipairs(packs) do
			local path, length, name = PackFile(pack, kind, old .. "-" .. kind)
			if path then
				Trace("%s %q: quest %d has no file; recorded as quest %d (same title)", kind, tostring(title), questID, old)
				return path, length, name
			end
		end
	end
	Trace("%s %q: quest %d has no %s recording in the pack", kind, tostring(title), questID, kind)
	return nil
end

-- Recorded file for a greeting: path, length in seconds.
local function PackGossipLine(npc, text)
	if type(text) ~= "string" or IsSecret(text) or not npc then
		return nil
	end
	local who = string.format("%s (%s)", tostring(npc.name), tostring(npc.id))
	local found = false
	for _, pack in ipairs(packs) do
		local entries
		if npc.id and pack.data.GossipLookupByNPCID then
			entries = pack.data.GossipLookupByNPCID[npc.id]
		end
		if not entries and npc.name and pack.data.GossipLookupByNPCName then
			entries = pack.data.GossipLookupByNPCName[Unquote(npc.name)]
		end
		if entries then
			found = true
			local hash, score = BestMatch(text, entries, 0.4)
			if hash then
				local path, length, name = PackFile(pack, "gossip", hash)
				if path then
					Trace("greeting from %s: matched %d%%, recorded", who, math.floor(score * 100 + 0.5))
					return path, length, nil, name
				end
				Trace("greeting from %s: matched %d%% but the file is missing", who, math.floor(score * 100 + 0.5))
			else
				local _, best = BestMatch(text, entries, 0)
				local onlyHash, count = nil, 0
				for _, h in pairs(entries) do
					onlyHash = h
					count = count + 1
				end
				if M.db.preferRecordings and count == 1 then
					local path, length, name = PackFile(pack, "gossip", onlyHash)
					if path then
						Trace("greeting from %s: text differs (%d%% match) but Prefer Recordings plays the NPC's only recording", who, math.floor((best or 0) * 100 + 0.5))
						return path, length, true, name
					end
				end
				Trace("greeting from %s: best match only %d%%, below the 40%% needed", who, math.floor((best or 0) * 100 + 0.5))
			end
		end
	end
	if not found then
		Trace("greeting from %s: NPC has no recorded greetings in the pack", who)
	end
	return nil
end

local function StopFile()
	if activeHandle then
		pcall(StopSound, activeHandle)
		activeHandle = nil
	end
end

--------------------------------------------------------------------------------
-- Line collector
--
-- Records the dialog lines seen in play into the MelloUIVoiceLines saved
-- variable so Tools\export_voice_lines.py can build the list of lines that
-- need recording for a Forever sound pack. On this beta the client writes
-- the file on /reload but never reads it back, so the export script merges
-- each session into its own store.
--------------------------------------------------------------------------------

local KINDS = {
	gossip   = { label = "Greeting",       bullet = "SoundQueueBulletGossip",   quest = false },
	accept   = { label = "Quest offer",    bullet = "SoundQueueBulletAccept",   quest = true },
	progress = { label = "Quest progress", bullet = "SoundQueueBulletProgress", quest = true },
	complete = { label = "Quest turn-in",  bullet = "SoundQueueBulletComplete", quest = true },
	objectives = { label = "Objectives",   bullet = "SoundQueueBulletProgress", quest = true, log = true },
}

local function PlainUnitValue(fn, unit)
	local ok, value = pcall(fn, unit)
	if ok and type(value) == "string" and not IsSecret(value) and value ~= "" then
		return value
	end
	return nil
end

local function Collected()
	if type(MelloUIVoiceLines) ~= "table" then
		MelloUIVoiceLines = {}
	end
	local store = MelloUIVoiceLines
	store.quests = store.quests or {}
	store.gossip = store.gossip or {}
	store.npcs = store.npcs or {}
	store.build = select(2, GetBuildInfo())
	store.player = store.player or {
		name = PlainUnitValue(UnitName, "player"),
		class = PlainUnitValue(UnitClass, "player"),
		race = PlainUnitValue(UnitRace, "player"),
	}
	return store
end

-- Put the placeholders back that the server filled in ($n name, $c class,
-- $r race), so the stored text is the same for every character and the
-- recording can say "adventurer" instead of one player's name.
local function Placeholdered(text, player)
	if type(text) ~= "string" or not player then
		return text
	end
	local function Swap(value, placeholder)
		if type(value) ~= "string" or value == "" then
			return
		end
		local pattern = "%f[%w]" .. value:gsub("%p", "%%%0") .. "%f[%W]"
		text = text:gsub(pattern, placeholder)
		local lower = value:lower()
		if lower ~= value then
			text = text:gsub("%f[%w]" .. lower:gsub("%p", "%%%0") .. "%f[%W]", placeholder)
		end
	end
	Swap(player.name, "$n")
	Swap(player.class, "$c")
	Swap(player.race, "$r")
	return text
end

local function CollectNPC(store, npc)
	if not npc or not npc.id then
		return
	end
	local rec = store.npcs[npc.id] or {}
	rec.name = npc.name or rec.name
	rec.gender = npc.gender or rec.gender
	rec.race = npc.race or rec.race
	rec.source = npc.source or rec.source
	if npc.unit then
		local ok, creatureType = pcall(UnitCreatureType, npc.unit)
		if ok and type(creatureType) == "string" and not IsSecret(creatureType) then
			rec.type = creatureType
		end
	end
	-- Where we are standing while talking is, near enough, where the NPC is:
	-- the quest list uses it as the pick-up location for NPCs no database knows.
	if not npc.remote and C_Map and C_Map.GetBestMapForUnit and C_Map.GetPlayerMapPosition then
		local okMap, mapID = pcall(C_Map.GetBestMapForUnit, "player")
		if okMap and IsPlainNumber(mapID) then
			local okPos, pos = pcall(C_Map.GetPlayerMapPosition, mapID, "player")
			if okPos and pos then
				local okXY, x, y = pcall(pos.GetXY, pos)
				if okXY and IsPlainNumber(x) and IsPlainNumber(y) then
					local okInfo, info = pcall(C_Map.GetMapInfo, mapID)
					rec.map = mapID
					rec.mapName = okInfo and info and not IsSecret(info.name) and info.name or rec.mapName
					rec.x = math.floor(x * 1000 + 0.5) / 10
					rec.y = math.floor(y * 1000 + 0.5) / 10
				end
			end
		end
	end
	store.npcs[npc.id] = rec
end

local unsavedLines = 0

local function CollectLine(entry, questID)
	if not M.db.collectLines or entry.secret or type(entry.text) ~= "string" then
		return
	end
	local store = Collected()
	local npc = entry.npc
	CollectNPC(store, npc)
	local info = KINDS[entry.kind] or KINDS.gossip
	local text = Placeholdered(entry.text, store.player)
	local rec = {
		text = text,
		npc = npc and npc.name or nil,
		npcID = npc and npc.id or nil,
		-- A recording with the right words played, from any pack. (The merged
		-- MelloUI_VoiceOverData pack carries the vanilla lines too, so the old
		-- "not our own pack" rule marked every recorded line as missing and
		-- nagged about new lines that had a recording.) "file" is the
		-- recording's name, so Tools/export_voice_lines.py can tell a line
		-- served by another quest's file (a renumbered quest) from a new one.
		recorded = entry.file ~= nil and not entry.mismatch,
		file = (entry.file ~= nil and not entry.mismatch) and entry.fileName or nil,
		seen = date("%Y-%m-%d"),
	}
	local isNew
	if info.quest then
		local key = questID and tostring(questID) or ("title:" .. tostring(entry.title))
		store.quests[key] = store.quests[key] or {}
		rec.title = entry.title
		isNew = store.quests[key][entry.kind] == nil
		store.quests[key][entry.kind] = rec
	else
		local id = npc and npc.id or 0
		store.gossip[id] = store.gossip[id] or {}
		isNew = store.gossip[id][text] == nil
		store.gossip[id][text] = rec
	end
	-- Lines only reach the disk on /reload; nudge now and then.
	if isNew and not rec.recorded then
		unsavedLines = unsavedLines + 1
		if unsavedLines % 5 == 0 then
			MelloUI:Notice("Voice Over: %d new lines without a recording collected (Record Dialog Lines). /reload saves them.", unsavedLines)
		end
	end
end

--------------------------------------------------------------------------------
-- Speech queue
--
-- Lines are queued and read one after another, like the VoiceOver addon:
-- a greeting is not cut off by the quest that follows it. The queue advances
-- on the client's playback finished event, with an estimated duration as a
-- fallback in case the event never arrives.
--------------------------------------------------------------------------------

local queue = {}          -- waiting entries
local current = nil       -- entry being spoken
local paused = false
local entryCounter = 0
local finishTimer = nil
local failedWarned = false
local Overlay             -- forward declaration, defined below

local function TexturePath(name)
	return "Interface\\AddOns\\" .. ADDON_NAME .. "\\Media\\Textures\\VoiceOver\\" .. name
end

local function CancelFinishTimer()
	if finishTimer then
		finishTimer:Cancel()
		finishTimer = nil
	end
end

local function StopEngine()
	StopFile()
	if HasTTS() and C_VoiceChat.StopSpeakingText then
		pcall(C_VoiceChat.StopSpeakingText)
	end
end

-- Rough reading time so the queue still moves if no finished event comes.
local function EstimateSeconds(text, rate)
	local words = 12
	if type(text) == "string" and not IsSecret(text) then
		words = select(2, text:gsub("%S+", ""))
	end
	local perSecond = 2.3 * (1 + (rate or 0) * 0.06)
	return math.max(3, words / perSecond + 3)
end

-- Send one entry to the speech engine, or play its recorded file. Returns
-- true if it started.
local function SpeakEntry(entry)
	if entry.file then
		StopEngine()
		local ok, willPlay, handle = pcall(PlaySoundFile, entry.file, M.db.soundChannel or "Master")
		if ok and willPlay then
			activeHandle = handle
			return true
		end
		-- File missing or channel muted: fall back to speech.
		entry.file = nil
		entry.length = nil
	end
	local npc = entry.npc
	local race = npc and npc.race or nil
	local female = npc and npc.female or false
	local voiceID = PickVoice(race, female)
	if voiceID == nil then
		if not failedWarned then
			failedWarned = true
			MelloUI:Print("Voice Over: no text-to-speech voices installed. Add voices in Windows speech settings.")
		end
		return false
	end
	local pitch, rate = VoiceShape(race)
	local text = entry.text
	-- Pitch is only reachable through the speech engine's XML tags, which
	-- means the text has to be escaped; secret text cannot be, so it is read
	-- at the voice's natural pitch.
	if pitch ~= 0 and not entry.secret then
		text = string.format('<pitch absmiddle="%d"/>%s', pitch, EscapeXML(text))
	end
	StopEngine()
	local volume = tonumber(M.db.volume) or 100
	local ok = pcall(C_VoiceChat.SpeakText, voiceID, text, rate, volume, false)
	return ok
end

local PlayNext

local function OnFinished(entry)
	if entry ~= current then
		return
	end
	CancelFinishTimer()
	current = nil
	if not paused then
		PlayNext()
	end
	Overlay:Update()
end

local function StartEntry(entry)
	current = entry
	entry.startedAt = GetTime()
	CancelFinishTimer()
	if not SpeakEntry(entry) then
		current = nil
		return false
	end
	local seconds
	if entry.file and entry.length then
		seconds = entry.length + 0.5
	else
		local _, rate = VoiceShape(entry.npc and entry.npc.race or nil)
		seconds = EstimateSeconds(entry.text, rate)
	end
	entry.expected = seconds
	finishTimer = C_Timer.NewTimer(seconds, function()
		finishTimer = nil
		OnFinished(entry)
	end)
	return true
end

PlayNext = function()
	while not current and #queue > 0 do
		local entry = table.remove(queue, 1)
		if StartEntry(entry) then
			break
		end
	end
end

local function IsPlaying()
	return current ~= nil and not paused
end

local function Stop()
	CancelFinishTimer()
	wipe(queue)
	current = nil
	StopEngine()
	Overlay:Update()
end

local function Skip(entry)
	if entry == current then
		CancelFinishTimer()
		current = nil
		StopEngine()
		if not paused then
			PlayNext()
		end
	else
		for i, queued in ipairs(queue) do
			if queued == entry then
				table.remove(queue, i)
				break
			end
		end
	end
	Overlay:Update()
end

local function SetPaused(state)
	if paused == state then
		return
	end
	paused = state
	if paused then
		CancelFinishTimer()
		StopEngine()
	else
		if current then
			-- Text-to-speech cannot resume mid sentence; the line restarts.
			StartEntry(current)
		else
			PlayNext()
		end
	end
	Overlay:Update()
end

local function TogglePaused()
	SetPaused(not paused)
end

-- Queue a line. npc is a table from DescribeNPC (or nil), kind a KINDS key.
-- matchText, when given, is the text the pack lookups compare (the quest
-- description alone when the objectives are read after it).
local function Enqueue(text, npc, kind, title, questID, matchText)
	if not HasTTS() then
		return
	end
	text = CleanText(text)
	if text == nil then
		return
	end
	local secret = IsSecret(text)
	if not secret then
		if text == "" then
			return
		end
		-- The same window can fire its event twice (e.g. QUEST_DETAIL on
		-- refresh); do not queue identical text again.
		if current and current.text == text then
			return
		end
		for _, entry in ipairs(queue) do
			if entry.text == text then
				return
			end
		end
	end
	local info = KINDS[kind] or KINDS.gossip
	if M.db.queueLines then
		-- A greeting never waits behind a quest line (the player has already
		-- moved on to the quest).
		if not info.quest then
			if current and KINDS[current.kind].quest then
				return
			end
			for _, entry in ipairs(queue) do
				if KINDS[entry.kind].quest then
					return
				end
			end
		end
	else
		CancelFinishTimer()
		wipe(queue)
		current = nil
	end
	entryCounter = entryCounter + 1
	local entry = {
		id = entryCounter,
		text = text,
		secret = secret,
		npc = npc,
		kind = kind,
		title = title or info.label,
		name = npc and npc.name or nil,
	}
	if M.db.soundPacks and not info.log then
		-- The pack tables also resolve quest IDs the client does not give.
		LoadSoundPacks()
	end
	matchText = matchText or text
	if info.quest and not questID then
		questID = ResolveQuestID(kind, npc, title, matchText)
	end
	entry.questID = questID
	if M.db.soundPacks and not info.log and #packs > 0 then
		local path, length, mismatch, fileName
		if info.quest then
			path, length, fileName = PackQuestLine(kind, npc, title, matchText, questID)
		else
			path, length, mismatch, fileName = PackGossipLine(npc, text)
		end
		entry.file = path
		entry.length = length
		entry.mismatch = mismatch or nil
		entry.fileName = fileName
	end
	if not info.log then
		CollectLine(entry, questID)
	end
	queue[#queue + 1] = entry
	if not current and not paused then
		PlayNext()
	end
	Overlay:Update()
end

-- Speak a line straight away outside the queue (settings samples).
local function SpeakSample(text, npc)
	if not HasTTS() then
		return
	end
	CancelFinishTimer()
	current = nil
	SpeakEntry({ text = text, secret = false, npc = npc })
	Overlay:Update()
end

--------------------------------------------------------------------------------
-- Overlay
--
-- A movable frame with the speaking NPC's 3D portrait (playing its talk
-- animation), the NPC name, the line being read and the lines waiting.
-- Layout and textures follow the VoiceOver addon (MIT licence).
--------------------------------------------------------------------------------

-- The window is one picture (Media/Textures/VoiceOver/ScrollFrame, shipped
-- as a BLP; made from docs/voiceover-frame.webp): a dark square on the left
-- holding the model, a parchment scroll on the right holding the text. The
-- areas were measured on the 2000 x 668 art and scaled to FRAME_W.
local FRAME_W, FRAME_H = 600, 200
local ART_SCALE = FRAME_W / 2000
local TEX_BOTTOM = 342 / 512     -- the art fills the top 342 rows of the 1024 x 512 texture
local PORTRAIT_X, PORTRAIT_Y = 118 * ART_SCALE, 78 * ART_SCALE
local PORTRAIT_SIZE = (640 - 118) * ART_SCALE
local PARCHMENT_LEFT, PARCHMENT_RIGHT = 720 * ART_SCALE, 1860 * ART_SCALE
local ATLAS = 512
local ATLAS_BORDER = 416
local ATLAS_VIEWPORT = 348
local BORDER_SCALE = PORTRAIT_SIZE / ATLAS_VIEWPORT
local BORDER_OUTSET = 34 * BORDER_SCALE
local LINE_WIDTH = 56 * BORDER_SCALE
local MAX_LINES = 4
local TALK_ANIMATION = 60
local VALID_POINTS = {
	TOPLEFT = true, TOP = true, TOPRIGHT = true, LEFT = true, CENTER = true,
	RIGHT = true, BOTTOMLEFT = true, BOTTOM = true, BOTTOMRIGHT = true,
}

-- Talk animation length in seconds by model file ID (from the VoiceOver
-- addon). Models not listed loop every two seconds.
local TALK_DURATION = {
	[116921] = 4.0, [1100258] = 4.0, [117170] = 2.0, [1100087] = 2.0,
	[117437] = 3.0, [1022598] = 3.0, [117721] = 3.334, [1005887] = 3.334,
	[118135] = 2.0, [950080] = 2.0, [118355] = 2.0, [878772] = 2.0,
	[119063] = 4.0, [940356] = 4.0, [119159] = 4.0, [900914] = 4.0,
	[119369] = 1.8, [119376] = 1.8,
	[119563] = 2.667, [1000764] = 2.667, [119940] = 2.0, [1011653] = 2.0,
	[120263] = 3.0, [120294] = 3.0,
	[120590] = 2.1, [921844] = 2.1, [120791] = 2.0, [974343] = 2.0,
	[121087] = 2.0, [949470] = 2.0, [121287] = 2.0, [917116] = 2.0,
	[121608] = 2.0, [997378] = 2.467, [121768] = 2.667, [959310] = 2.667,
	[121942] = 2.667, [121961] = 2.934, [986648] = 2.934, [122055] = 2.934, [968705] = 2.934,
	[122414] = 2.5, [1018060] = 2.5, [122560] = 2.5, [1022938] = 2.5,
}

Overlay = { lines = {} }

local nameFont, lineFont, subtitleFont

local function EnsureFonts()
	if nameFont then
		return
	end
	local path = GameFontNormal:GetFont()
	nameFont = CreateFont("MelloUIVoiceOverNameFont")
	nameFont:SetFont(path, 19, "")
	nameFont:SetShadowColor(1, 0.95, 0.8, 0.35)
	nameFont:SetShadowOffset(1, -1)
	nameFont:SetJustifyH("LEFT")
	lineFont = CreateFont("MelloUIVoiceOverLineFont")
	lineFont:SetFont(path, 16, "")
	lineFont:SetShadowOffset(0, 0)
	lineFont:SetJustifyH("LEFT")
	subtitleFont = CreateFont("MelloUIVoiceOverSubtitleFont")
	subtitleFont:SetFont(path, 12, "")
	subtitleFont:SetShadowOffset(0, 0)
	subtitleFont:SetJustifyH("LEFT")
	subtitleFont:SetJustifyV("TOP")
end

local function SetAtlasTexture(texture, left, right, top, bottom)
	texture:SetTexture(TexturePath("PortraitFrameAtlas"))
	texture:SetTexCoord(left / ATLAS, right / ATLAS, top / ATLAS, bottom / ATLAS)
end

--------------------------------------------------------------------------------
-- The painted kit's dress (user, 2026-09-24: "VoiceOver Overlay Reskin with
-- all 3 Presets"). While the reskin is on (UI Modifications, Painted kit
-- reskin: the whole interface, as the configurator and Dynamic UI
-- Modification read it -- the overlay is no window or HUD area of its own),
-- the one picture gives way to the kit's pieces, like every other small kit
-- window (the whisper popup, the Dynamic UI panels): the single rail with
-- its stone, the portrait ring round the speaker's model, a parchment sheet
-- with the painted edge on the stone for the lines, the speaker's name on a
-- title plate riding the top rail, and the kit's close / arrow glyphs for
-- stop / skip. Every piece goes through Kit:Apply, so Kit:SetKitColours
-- re-points it when the player picks Warm iron, Bronze or Original: the
-- three looks switch live, with nothing baked. With the reskin off the
-- picture is shown exactly as before, laid out as before.
--------------------------------------------------------------------------------

local KIT_LAYOUT = {
	ring = 190,                   -- the portrait ring's height: the window's 200 less a little, so it stands on the rails like a medallion
	ringX = 100,                  -- the ring's centre, right of the window's left edge (its left rim over the left rail)
	fill = 0.97,                  -- the model's square in the ring's opening: its corners stay under the ring's body
	paper = { 196, 20, 14, 14 },  -- the parchment's rect: left, top, right, bottom in from the window's edges (the top clear of the plate)
	plateBox = 26,                -- the name plate's painted box, UI px tall: a window title plate's height
	plateL = 190, plateR = 8,     -- the plate's ends, in from the window's left and right edges (over the parchment, clear of the ring)
	stop = { 23, 21 },            -- the stop / skip glyph's box (the close piece is 64 x 58)
	stopW = 26,                   -- the room the stop button takes from the lines, beside the padlock's
}

-- The text's colours. On the painted picture, the warm browns it always had;
-- in the kit, the parchment inks every other parchment in the UI uses
-- (MelloUI.QuestInk: the body ink for the line being read and the subtitle,
-- the faded ink for the queue, the skip red and the quest gold darkened to
-- the ink's contrast), since the line is dark ink on parchment either way.
local INKS = {
	art = {
		hover = { 0.62, 0.10, 0.04 }, quest = { 0.55, 0.36, 0.03 }, current = { 0.22, 0.13, 0.05 },
		queued = { 0.45, 0.36, 0.26 }, subtitle = { 0.24, 0.14, 0.05 },
	},
}

-- The kit when the overlay's look switch is on (Kit:IsOn('voiceover'): the
-- reskin, UI Modifications on with its Painted kit reskin -- the one answer
-- every own window asks, audit 2026-09-24 rank 1) and the kit has what the
-- dress needs, else nil.
local function ReskinKit()
	local Kit = MelloUI.Kit
	if not (Kit and Kit.NineSlice and Kit.Strip and Kit.Texture and Kit.Piece and Kit.ParchmentSheet and Kit.StateTexture) then
		return nil
	end
	if Kit.IsOn and Kit:IsOn("voiceover") then
		return Kit
	end
	return nil
end

--------------------------------------------------------------------------------
-- The overlay's place is the one mover's (audit, 2026-09-24, rank 6): kept
-- in the one store under 'voiceOverlay' (UI Modifications' positions, so
-- profiles, the backup and Reset positions reach it), saved by its bottom
-- edge's middle, where it first stands (over the action bars). Dragged
-- while its padlock is open, as before; moved, and sized by the wheel,
-- like every window while the windows are unlocked.
--------------------------------------------------------------------------------

local OVERLAY_PLACE = "voiceOverlay"

local function DefaultPlace(frame)
	frame:ClearAllPoints()
	frame:SetPoint("BOTTOM", UIParent, "BOTTOM", 0, 200)
end

-- Settings can come back from the macro backup with stray whitespace;
-- only a clean anchor name is taken.
local function Anchor(value)
	if type(value) ~= "string" then
		return nil
	end
	value = value:gsub("%s+", ""):upper()
	if VALID_POINTS[value] then
		return value
	end
	return nil
end

-- The old place (overlayPoint, overlayRelativePoint, overlayX, overlayY:
-- the overlay's point, the screen's point it hung from, the offsets in its
-- own units) moved into the store, as exactly that, so it stays where it
-- was; the old keys go with the move. Written in the store's own form (as
-- SavePosition writes it: point nil = BOTTOMLEFT, relPoint nil = CENTER)
-- and told through the setting path, as the mover's own saves are. The old
-- keys themselves are the version: nothing writes them any more, so they
-- are there only from before, or from a profile, share string or backup
-- written in the old form (the built-in profile is), and then they are the
-- place wanted. A flag instead could be set on the stand-in settings Core
-- uses until the saved ones arrive, be carried into those (Core's
-- AdoptSavedVariables) and stop the move.
local function MoveOldPlace()
	local db = M.db
	if not db or (db.overlayPoint == nil and db.overlayRelativePoint == nil and db.overlayX == nil and db.overlayY == nil) then
		return
	end
	local point = Anchor(db.overlayPoint)
	if point then
		local um = MelloUI:GetModuleDB("UIModifications")
		if type(um) ~= "table" then
			return   -- (no store: moved on a later try)
		end
		if type(um.positions) ~= "table" then
			um.positions = {}
		end
		local relPoint = Anchor(db.overlayRelativePoint) or point
		um.positions[OVERLAY_PLACE] = {
			point = point ~= "BOTTOMLEFT" and point or nil,
			relPoint = relPoint ~= "CENTER" and relPoint or nil,
			x = tonumber(db.overlayX) or 0, y = tonumber(db.overlayY) or 0,
		}
		MelloUI:NotifySettingChanged("UIModifications", "positions", um.positions)
	end
	db.overlayPoint, db.overlayRelativePoint, db.overlayX, db.overlayY = nil, nil, nil, nil
end

-- Let go after a drag (the mover's plain drag, its buttons', or the mover
-- of the unlocked windows): saved, and hung from its anchor again. The
-- overlay keeps its place itself (the mover's `save`: laid by Apply, as it
-- always was), and a scale the unlocked mover's wheel gave it is its
-- Overlay Scale setting, as the Quest Tracker's wheel is its Scale (a
-- scale in the store would undo the slider at every Apply).
local function SaveOverlay(frame)
	if not (frame and M.db) then
		return
	end
	local ok, scaled = pcall(frame.GetScale, frame)
	if MelloUI:SavePosition(OVERLAY_PLACE, frame, false) then
		MelloUI:RestorePosition(OVERLAY_PLACE, frame)
	end
	if ok and IsPlainNumber(scaled) and math.abs(scaled - (tonumber(M.db.overlayScale) or 1)) > 0.001 then
		M.db.overlayScale = math.floor(scaled * 100 + 0.5) / 100
		MelloUI:NotifySettingChanged(M.name, "overlayScale", M.db.overlayScale)
	end
end

function Overlay:SavePosition()
	SaveOverlay(self.frame)
end

function Overlay:RestorePosition()
	local frame = self.frame
	MoveOldPlace()
	if not MelloUI:RestorePosition(OVERLAY_PLACE, frame) then
		DefaultPlace(frame)
	end
end

-- the place forgotten, the old keys too (/vo reset)
local function ForgetOverlayPlace()
	if M.db then
		M.db.overlayPoint, M.db.overlayRelativePoint, M.db.overlayX, M.db.overlayY = nil, nil, nil, nil
	end
	MelloUI:ForgetPosition(OVERLAY_PLACE)
end

function Overlay:ResetPosition()
	ForgetOverlayPlace()
	if self.frame then
		self:RestorePosition()
	end
end

-- Reset positions (UI Modifications): back where it first stands, at its
-- standard size, as every window goes back (the Quest Tracker's scale too)
local function ResetOverlay()
	ForgetOverlayPlace()
	if M.db and math.abs((tonumber(M.db.overlayScale) or 1) - 1) > 0.001 then
		M.db.overlayScale = 1
		MelloUI:NotifySettingChanged(M.name, "overlayScale", 1)
	end
end

-- The mover drags by the overlay itself; its buttons (pause, stop, the
-- lines) drag it too, so it is grabbed anywhere, as it always was. The
-- mover takes one handle a window, so theirs start the same plain drag on
-- the overlay -- only while its padlock is open -- and end it as the mover
-- does (saved, hung from its anchor again). Marked as the mover's drag
-- (entry.moving), so a hide mid-drag, the next drag or the next show ends
-- it as any other. One pair of handlers for every button.
local ButtonDragStart = Perf.Shared("OnDragStart on the Voice Over overlay's buttons", function()
	local entry, frame = Overlay.mover, Overlay.frame
	if not (entry and frame) or entry.moving or entry.plainDrag ~= "always" then
		return
	end
	frame:StartMoving()
	entry.moving = "plain"
end, "script")

local ButtonDragStop = Perf.Shared("OnDragStop on the Voice Over overlay's buttons", function()
	local entry, frame = Overlay.mover, Overlay.frame
	if not (entry and frame and entry.moving == "plain") then
		return
	end
	entry.moving = nil
	frame:StopMovingOrSizing()
	Overlay:SavePosition()
end, "script")

local function AttachDrag(widget)
	widget:RegisterForDrag("LeftButton")
	Perf.SetScript(widget, "OnDragStart", ButtonDragStart)
	Perf.SetScript(widget, "OnDragStop", ButtonDragStop)
end

-- the padlock's meaning for the mover: dragged at any time while it is
-- open, never while it is shut (the unlocked windows' mover aside)
local function FollowPadlock()
	local entry = Overlay.mover
	if entry and M.db then
		entry.plainDrag = (not M.db.overlayLock) and "always" or false
	end
end

-- The one mover, the overlay itself its handle, from its first show
-- (WINDOW-RULES 2f: nothing made for it at login, and it is dragged only
-- once shown). Registered as dragged at any time, so the unlocked windows'
-- mover leaves its mouse on (its tooltip, its drag once the padlock
-- opens), then told the padlock; the wheel's range is the Overlay Scale
-- slider's. (false: the mover gave no entry; not asked again.)
local OVERLAY_MOVER = { key = OVERLAY_PLACE, anchor = "BOTTOM", plainDrag = "always",
	save = SaveOverlay, reset = ResetOverlay, default = DefaultPlace, min = 0.6, max = 1.5 }

local function RegisterOverlayMover(frame)
	-- laid from the store once more first: Reset positions before this
	-- first show wiped the store but could not reach an overlay the mover
	-- did not know yet, and with a `save` the mover lays nothing on show
	-- (review, 2026-09-25); unchanged when nothing was reset
	Overlay:RestorePosition()
	Overlay.mover = MelloUI:RegisterMover(frame, frame, OVERLAY_MOVER) or false
	FollowPadlock()
end

-- Frame the head and shoulders. The custom camera used by the VoiceOver
-- addon shows the legs on this client, so the portrait zoom is used instead.
local function AimCamera(model)
	pcall(model.SetPortraitZoom, model, 0.85)
	pcall(model.SetPosition, model, 0, 0, 0)
	pcall(model.SetRotation, model, 0)
end

function Overlay:CreatePortrait()
	local frame = self.frame
	local portrait = CreateFrame("Frame", nil, frame)
	portrait:SetPoint("TOPLEFT", PORTRAIT_X, -PORTRAIT_Y)
	portrait:SetSize(PORTRAIT_SIZE, PORTRAIT_SIZE)
	frame.portrait = portrait

	local model = CreateFrame("DressUpModel", nil, portrait)
	model:SetAllPoints()
	portrait.model = model
	model.creatureID = nil
	Perf.SetScript(model, "OnHide", function(self)
		pcall(self.ClearModel, self)
		self.creatureID = nil
		self.loaded = nil
		self.retries = nil
		self.retryIn = nil
		self.animation = nil
		self.animStart = nil
	end)
	Perf.SetScript(model, "OnUpdate", function(self, elapsed)
		if not self.creatureID then
			return
		end
		if not self.loaded then
			-- The creature may not be cached yet: ask again every half second,
			-- a few times, then leave whatever loaded alone.
			local ok, fileID = pcall(self.GetModelFileID, self)
			if ok and fileID then
				self.loaded = true
				self.fileID = fileID
				AimCamera(self)
			else
				self.retryIn = (self.retryIn or 0.5) - elapsed
				if self.retryIn > 0 then
					return
				end
				self.retryIn = 0.5
				self.retries = (self.retries or 0) + 1
				if self.retries <= 8 then
					pcall(self.SetCreature, self, self.creatureID)
					AimCamera(self)
					return
				end
				self.loaded = true
			end
		end
		local playing = IsPlaying()
		local now = GetTime()
		local duration = TALK_DURATION[self.fileID or 0] or 2
		if playing then
			if self.animation ~= TALK_ANIMATION or now - (self.animStart or 0) >= duration then
				self.animation = TALK_ANIMATION
				self.animStart = now
				pcall(self.SetAnimation, self, TALK_ANIMATION)
			end
		elseif self.animation ~= 0 and now - (self.animStart or 0) >= duration then
			-- Let the current talk cycle finish, then go idle.
			self.animation = 0
			self.animStart = now
			pcall(self.SetAnimation, self, 0)
		end
	end)

	-- Book icon for NPCs whose model cannot be shown.
	portrait.book = portrait:CreateTexture(nil, "ARTWORK")
	portrait.book:SetAllPoints()
	portrait.book:SetTexture(TexturePath("Book"))
	portrait.book:SetTexCoord(8 / 256, 248 / 256, 8 / 256, 248 / 256)
	portrait.book:Hide()

	-- Pause button over the model; its background dims the model while paused.
	local pause = CreateFrame("Button", nil, portrait)
	pause:SetFrameLevel(model:GetFrameLevel() + 1)
	pause:SetAllPoints()
	pause.background = pause:CreateTexture(nil, "BACKGROUND")
	pause.background:SetAllPoints()
	pause.background:SetTexture(TexturePath("PortraitFrameBackground"))
	pause.background:SetAlpha(0.75)
	pause:SetNormalTexture(TexturePath("PortraitFrameAtlas"))
	pause:GetNormalTexture():ClearAllPoints()
	pause:GetNormalTexture():SetPoint("CENTER")
	pause:GetNormalTexture():SetSize(32, 32)
	pause:SetPushedTexture(TexturePath("PortraitFrameAtlas"))
	pause:GetPushedTexture():ClearAllPoints()
	pause:GetPushedTexture():SetPoint("CENTER")
	pause:GetPushedTexture():SetSize(28, 28)
	function pause:Update()
		local hovered = self:IsMouseOver()
		if paused then
			self.background:SetShown(true)
			SetAtlasTexture(self:GetNormalTexture(), 0, 93, 419, 512)
			SetAtlasTexture(self:GetPushedTexture(), 0, 93, 419, 512)
			self:GetNormalTexture():SetAlpha(hovered and 1 or 0.75)
		else
			self.background:Hide()
			SetAtlasTexture(self:GetNormalTexture(), 93, 186, 419, 512)
			SetAtlasTexture(self:GetPushedTexture(), 93, 186, 419, 512)
			self:GetNormalTexture():SetAlpha(hovered and 1 or 0)
		end
	end
	Perf.SetScript(pause, "OnEnter", function(self)
		self:GetNormalTexture():SetAlpha(1)
		GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
		GameTooltip:SetText(paused and "Resume" or "Pause")
		GameTooltip:Show()
	end)
	Perf.SetScript(pause, "OnLeave", function(self)
		self:GetNormalTexture():SetAlpha(paused and 0.75 or 0)
		GameTooltip:Hide()
	end)
	Perf.SetScript(pause, "OnClick", function()
		MelloUI:PlayUISound("tick")
		TogglePaused()
	end)
	AttachDrag(pause)
	portrait.pause = pause

	-- The art draws the frame around the square; nothing above the model.
	local border = CreateFrame("Frame", nil, portrait)
	border:SetFrameLevel(pause:GetFrameLevel() + 1)
	border:SetAllPoints()
	portrait.border = border

	-- Thin line and mini pause button used when the portrait is hidden.
	frame.portraitLine = frame:CreateTexture(nil, "BORDER")
	frame.portraitLine:SetPoint("TOPLEFT", -LINE_WIDTH / 2 + 2, BORDER_OUTSET)
	frame.portraitLine:SetPoint("BOTTOMRIGHT", frame, "BOTTOMLEFT", LINE_WIDTH / 2 + 2, -BORDER_OUTSET)
	SetAtlasTexture(frame.portraitLine, 456, 512, 0, ATLAS_BORDER)

	local mini = CreateFrame("Button", nil, frame)
	mini:SetSize(26, 26)
	mini:SetNormalTexture(TexturePath("PortraitFrameAtlas"))
	mini:GetNormalTexture():ClearAllPoints()
	mini:GetNormalTexture():SetPoint("CENTER")
	mini:GetNormalTexture():SetSize(14, 14)
	mini:SetPushedTexture(TexturePath("PortraitFrameAtlas"))
	mini:GetPushedTexture():ClearAllPoints()
	mini:GetPushedTexture():SetPoint("CENTER")
	mini:GetPushedTexture():SetSize(12, 12)
	mini.background = mini:CreateTexture(nil, "BACKGROUND")
	mini.background:SetTexture(TexturePath("SettingsButton"))
	mini.background:SetPoint("CENTER")
	mini.background:SetSize(32, 32)
	function mini:Update()
		if paused then
			SetAtlasTexture(self:GetNormalTexture(), 0, 93, 419, 512)
			SetAtlasTexture(self:GetPushedTexture(), 0, 93, 419, 512)
		else
			SetAtlasTexture(self:GetNormalTexture(), 93, 186, 419, 512)
			SetAtlasTexture(self:GetPushedTexture(), 93, 186, 419, 512)
		end
		self:GetNormalTexture():SetAlpha(self:IsMouseOver() and 1 or 0.75)
	end
	Perf.SetScript(mini, "OnEnter", function(self) self:GetNormalTexture():SetAlpha(1) end)
	Perf.SetScript(mini, "OnLeave", function(self) self:GetNormalTexture():SetAlpha(0.75) end)
	Perf.SetScript(mini, "OnClick", function()
		MelloUI:PlayUISound("tick")
		TogglePaused()
	end)
	AttachDrag(mini)
	frame.miniPause = mini
end

function Overlay:ConfigurePortrait(entry)
	local portrait = self.frame.portrait
	if not portrait:IsShown() then
		return
	end
	local model = portrait.model
	local npcID = entry and entry.npc and entry.npc.id or nil
	if not npcID then
		model:Hide()
		portrait.book:SetShown(entry ~= nil)
		return
	end
	portrait.book:Hide()
	model:Show()
	if model.creatureID ~= npcID then
		pcall(model.ClearModel, model)
		model.creatureID = npcID
		model.loaded = nil
		model.retries = nil
		model.retryIn = nil
		model.fileID = nil
		model.animation = nil
		model.animStart = nil
		pcall(model.SetCreature, model, npcID)
		AimCamera(model)
	end
end

function Overlay:CreateLine(index)
	local container = self.frame.container
	local button = CreateFrame("Button", nil, container)
	button:SetHeight(20)
	button.index = index
	button.text = button:CreateFontString(nil, "OVERLAY", "MelloUIVoiceOverLineFont")
	button.text:SetWordWrap(false)
	button.icon = button:CreateTexture(nil, "ARTWORK")
	button.icon:SetSize(16, 16)
	button.icon:SetPoint("CENTER", button, "LEFT", 8, 0)
	Perf.SetScript(button, "OnClick", function(self)
		if self.entry then
			MelloUI:PlayUISound("tick")
			Skip(self.entry)
		end
	end)
	AttachDrag(button)
	Perf.SetScript(button, "OnEnter", function(self)
		self.hovered = true
		self:Refresh()
		GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
		GameTooltip:SetText(self.entry == current and "Skip this line" or "Remove from queue")
		GameTooltip:Show()
	end)
	Perf.SetScript(button, "OnLeave", function(self)
		self.hovered = false
		self:Refresh()
		GameTooltip:Hide()
	end)
	function button:Refresh()
		local entry = self.entry
		if not entry then
			self:Hide()
			return
		end
		self:Show()
		local info = KINDS[entry.kind] or KINDS.gossip
		local isCurrent = entry == current
		local ink = Overlay:Ink()
		-- under the name on the picture; under the top of the parchment in the
		-- kit, where the name is on the plate (Overlay:Dress)
		local anchor = self.index == 1 and (container.head or container.name) or container.lines[self.index - 1]
		self:ClearAllPoints()
		if isCurrent then
			self:SetAlpha(1)
			self:SetPoint("TOPLEFT", anchor, "BOTTOMLEFT", 0, -2)
		else
			local position = self.index - (current and 1 or 0)
			self:SetAlpha(math.max(0.1, math.min(1, 1 - (position - 1) / 3)))
			self:SetPoint("TOPLEFT", anchor, "BOTTOMLEFT", 0, position == 1 and -8 or -2)
		end
		self.text:ClearAllPoints()
		self.text:SetPoint("LEFT", 16 + 5, 0)
		self.text:SetText(entry.title)
		local width = container:GetWidth()
		self:SetWidth(math.min(width, 16 + 5 + self.text:GetStringWidth() + 1))
		self.text:SetPoint("RIGHT")
		if self.hovered then
			self:SetAlpha(1)
			self.text:SetTextColor(unpack(ink.hover))
			self.icon:SetTexture(TexturePath("SoundQueueBulletDelete"))
			self.icon:SetSize(14, 14)
		elseif isCurrent then
			if info.quest then
				self.text:SetTextColor(unpack(ink.quest))
			else
				self.text:SetTextColor(unpack(ink.current))
			end
			self.icon:SetTexture(TexturePath(info.bullet))
			self.icon:SetSize(14, 14)
		else
			self.text:SetTextColor(unpack(ink.queued))
			self.icon:SetTexture(TexturePath("SoundQueueBulletQueue"))
			self.icon:SetSize(22, 22)
		end
	end
	container.lines[index] = button
	return button
end

function Overlay:Create()
	if self.frame then
		return
	end
	EnsureFonts()
	local frame = CreateFrame("Frame", "MelloUIVoiceOverFrame", UIParent)
	self.frame = frame
	frame:SetSize(FRAME_W, FRAME_H)
	frame:SetFrameStrata("MEDIUM")
	frame:SetMovable(true)
	frame:SetClampedToScreen(true)
	frame:EnableMouse(true)
	frame:RegisterForDrag("LeftButton")
	Perf.SetScript(frame, "OnEnter", function(self)
		if M.db.overlayLock then
			return
		end
		GameTooltip:SetOwner(self, "ANCHOR_TOP")
		GameTooltip:SetText("Voice Over")
		GameTooltip:AddLine("Drag to move. The padlock in the corner locks the position.", 1, 1, 1, true)
		GameTooltip:Show()
	end)
	Perf.SetScript(frame, "OnLeave", function() GameTooltip:Hide() end)
	frame:Hide()
	-- (its mover comes with its first show: Overlay:Update)

	frame.background = frame:CreateTexture(nil, "BACKGROUND")
	frame.background:SetAllPoints()
	frame.background:SetTexture(TexturePath("ScrollFrame"))
	frame.background:SetTexCoord(0, 1, 0, TEX_BOTTOM)
	-- the picture's parts, hidden while the kit dresses the window
	frame.artParts = { frame.background }

	-- The parchment as a sheet with painted edges (user, 2026-09-23: painted
	-- edges in more places, the voice-over window among them). The picture's
	-- own parchment is covered by a dark backing, and the same parchment,
	-- cut from the picture, lies on it with dry-brush strokes on every side
	-- (Kit:PaintedEdge), so the strokes show against the dark inside the iron
	-- frame and its gold trim, which stay as painted.
	local Kit = MelloUI.Kit
	if Kit and Kit.PaintedEdge then
		-- the parchment in the 1024 x 512 texture, and so in the window
		local u1, u2, v1, v2 = 352 / 1024, 982 / 1024, 58 / 512, 292 / 512
		local sx, sy = FRAME_W / 1024, FRAME_H / (TEX_BOTTOM * 512)
		local left, right = 352 * sx, 982 * sx
		local top, bottom = 58 * sy, 292 * sy
		local backing = frame:CreateTexture(nil, "BACKGROUND", nil, 1)
		backing:SetColorTexture(0.09, 0.07, 0.05, 1)
		backing:SetPoint("TOPLEFT", frame, "TOPLEFT", left, -top)
		backing:SetSize(right - left, bottom - top)
		local sheet = frame:CreateTexture(nil, "BACKGROUND", nil, 2)
		sheet:SetTexture(TexturePath("ScrollFrame"))
		sheet:SetTexCoord(u1, u2, v1, v2)
		-- in the kit's one parchment tone, as every other parchment
		local tint = Kit.parchmentTint
		if tint then
			sheet:SetVertexColor(tint[1], tint[2], tint[3])
		end
		sheet:SetAllPoints(backing)
		local edge = Kit:PaintedEdge(sheet, sheet, false, true)
		if edge then
			edge:Fit(right - left, bottom - top)
			frame.artParts[#frame.artParts + 1] = backing
			frame.artParts[#frame.artParts + 1] = sheet
		else
			backing:Hide()
			sheet:Hide()
		end
	end

	self:CreatePortrait()

	local container = CreateFrame("Frame", nil, frame)
	container:SetPoint("LEFT", frame, "LEFT", PARCHMENT_LEFT, -1)
	container.lines = {}
	frame.container = container

	container.name = container:CreateFontString(nil, "ARTWORK", "MelloUIVoiceOverNameFont")
	container.name:SetPoint("TOPLEFT")
	container.name:SetWordWrap(false)
	container.name:SetTextColor(0.30, 0.17, 0.05)
	-- what the first line hangs from: the name here, the parchment's top in
	-- the kit (Overlay:Dress)
	container.head = container.name

	-- Stop / skip button next to the name.
	local stop = CreateFrame("Button", nil, container)
	stop:SetSize(32, 32)
	stop:SetPoint("BOTTOMLEFT", container.name, "RIGHT", -6, 0)
	Perf.SetScript(stop, "OnEnter", function(self)
		GameTooltip:SetOwner(self, "ANCHOR_NONE")
		GameTooltip:SetPoint("LEFT", self, "RIGHT")
		GameTooltip:SetText(#queue > 0 and "Skip to next line" or "Stop")
		GameTooltip:Show()
	end)
	Perf.SetScript(stop, "OnLeave", function() GameTooltip:Hide() end)
	Perf.SetScript(stop, "OnClick", function()
		MelloUI:PlayUISound("tick")
		if current then
			Skip(current)
		else
			Stop()
		end
	end)
	function stop:Refresh()
		local dress = Overlay.kitOn and Overlay.dress
		local more = #queue > 0
		if dress then
			-- the kit's glyphs: its close cross to stop, its arrow to skip on
			-- to the next line; the picture's own textures kept but unseen
			for _, get in ipairs({ self.GetNormalTexture, self.GetPushedTexture, self.GetHighlightTexture }) do
				local tex = get(self)
				if tex then
					tex:SetAlpha(0)
				end
			end
			dress.skip:SetShown(more)
			dress.stopX:SetShown(not more)
			return
		end
		if Overlay.dress then
			Overlay.dress.skip:Hide()
			Overlay.dress.stopX:Hide()
		end
		local texture = TexturePath(more and "StopGossipMore" or "StopGossip")
		self:SetNormalTexture(texture)
		self:SetPushedTexture(texture)
		self:SetHighlightTexture(texture, "ADD")
		self:GetNormalTexture():SetAlpha(1)
		self:GetPushedTexture():SetAlpha(0.5)
		self:GetHighlightTexture():SetAlpha(0.5)
	end
	stop:Refresh()
	AttachDrag(stop)
	container.stop = stop

	-- Padlock in the corner: locks and unlocks the window's position.
	local lock = CreateFrame("Button", nil, frame)
	lock:SetSize(26, 26)
	-- inside the parchment, top right
	lock:SetPoint("TOPRIGHT", frame, "TOPRIGHT", -(FRAME_W - PARCHMENT_RIGHT) - 2, -34)
	lock:SetFrameLevel(frame:GetFrameLevel() + 5)
	function lock:Refresh()
		local locked = M.db.overlayLock
		local texture = locked and "Interface/Buttons/LockButton-Locked-Up" or "Interface/Buttons/LockButton-Unlocked-Up"
		self:SetNormalTexture(texture)
		self:SetPushedTexture(locked and "Interface/Buttons/LockButton-Locked-Down" or "Interface/Buttons/LockButton-Unlocked-Down")
		self:SetHighlightTexture(texture, "ADD")
		self:GetHighlightTexture():SetAlpha(0.4)
		self:SetAlpha(locked and 0.55 or 0.9)
	end
	Perf.SetScript(lock, "OnClick", function(self)
		M.db.overlayLock = not M.db.overlayLock
		MelloUI:NotifySettingChanged(M.name, "overlayLock", M.db.overlayLock)
		MelloUI:PlayUISound(M.db.overlayLock and "option_on" or "option_off")
		self:Refresh()
		GameTooltip:Hide()
	end)
	Perf.SetScript(lock, "OnEnter", function(self)
		GameTooltip:SetOwner(self, "ANCHOR_NONE")
		GameTooltip:SetPoint("LEFT", self, "RIGHT", 4, 0)
		GameTooltip:SetText(M.db.overlayLock and "Position locked" or "Position unlocked")
		GameTooltip:AddLine(M.db.overlayLock and "Click to unlock and drag the window." or "Drag the window to move it. Click to lock it in place.", 1, 1, 1, true)
		GameTooltip:Show()
	end)
	Perf.SetScript(lock, "OnLeave", function() GameTooltip:Hide() end)
	lock:Refresh()
	frame.lock = lock

	container.subtitle = container:CreateFontString(nil, "ARTWORK", "MelloUIVoiceOverSubtitleFont")
	container.subtitle:SetWordWrap(true)
	container.subtitle:SetMaxLines(3)
	container.subtitle:SetTextColor(0.24, 0.14, 0.05)
	container.subtitle:Hide()
	-- each new page fades in (a quarter of a second, easing out) instead of
	-- jumping in: the reading eye follows it (played through Anim:PlayGroup,
	-- which ends it at once under Reduce Motion)
	local fade = container.subtitle:CreateAnimationGroup()
	local alpha = fade:CreateAnimation("Alpha")
	alpha:SetFromAlpha(0)
	alpha:SetToAlpha(1)
	alpha:SetDuration(0.25)
	alpha:SetSmoothing("OUT")
	fade:SetToFinalAlpha(true)
	container.subtitle.fade = fade
	local pageAcc = 0
	Perf.SetScript(container, "OnUpdate", function(_, elapsed)
		pageAcc = pageAcc + elapsed
		if pageAcc < 0.1 then
			return
		end
		pageAcc = 0
		if current and current.pages and #current.pages > 1 and container.subtitle:IsShown() and Overlay.SubtitlePage then
			if Overlay.SubtitlePage(current) ~= current.page then
				Overlay:Update()
			end
		end
	end)

	self:Apply()
end

-- The text colours for the current dress (INKS above)
function Overlay:Ink()
	if not self.kitOn then
		return INKS.art
	end
	if not INKS.kit then
		local QI = MelloUI.QuestInk
		local art = INKS.art
		if QI and QI.INK and QI.InkOf then
			INKS.kit = {
				hover = { QI.InkOf(unpack(art.hover)) }, quest = { QI.InkOf(unpack(art.quest)) },
				current = QI.INK.text, queued = QI.INK.faded, subtitle = QI.INK.text,
			}
		else
			INKS.kit = art
		end
	end
	return INKS.kit
end

-- Build the kit's pieces once into `dress`, hidden (Overlay:Dress shows
-- them). Returns the dress, or nil when a piece it needs is missing.
function Overlay:BuildDress(Kit, dress)
	local frame, L = self.frame, KIT_LAYOUT
	local ringPiece = Kit:Piece("window/portrait_ring")
	if not (ringPiece and ringPiece.open and ringPiece.h and ringPiece.h > 0) then
		return nil
	end

	-- the single rail and its stone over the whole window, as the whisper
	-- popup and the Dynamic UI panels (no corner gems: on a window this
	-- small they bunch up)
	local skin = Kit:NineSlice(frame, { prefix = Kit.framePrefix, gems = false, scale = (Kit.scale or 1) * (Kit.frameScale or 1) })
	dress.skin = skin
	dress.parts[#dress.parts + 1] = skin

	-- the parchment the lines are read from, on the stone right of the ring,
	-- ending in the painted edge (Kit:ParchmentSheet: the vellum tile at the
	-- UI's one background density, in the kit's parchment tone, never
	-- stretched). Always there, as the picture's scroll always was: the
	-- overlay's text is written for parchment. A region of the skin, so it
	-- comes and goes with it.
	local paper = CreateFrame("Frame", nil, frame)
	paper:EnableMouse(false)
	paper:SetPoint("TOPLEFT", frame, "TOPLEFT", L.paper[1], -L.paper[2])
	paper:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", -L.paper[3], L.paper[4])
	dress.paper = paper
	dress.sheet, dress.edge = Kit:ParchmentSheet(skin, paper, { rect = paper, margin = 0, tight = true })

	-- the portrait ring on the left, a dark disc in its opening under the
	-- model (the palette's inner panel, round: the ring's body covers its
	-- rim), the ring itself above the model and the pause button
	local rscale = L.ring / ringPiece.h
	local open = ringPiece.open
	dress.portraitSize = (open[3] - open[1]) * rscale * L.fill
	local disc = skin:CreateTexture(nil, "BACKGROUND", nil, 4)
	local diameter = 2 * (ringPiece.radius or (ringPiece.w / 2)) * rscale
	disc:SetSize(diameter, diameter)
	disc:SetPoint("CENTER", frame, "LEFT", L.ringX, 0)
	local inner = MelloUI.Palette.innerPanel
	disc:SetColorTexture(inner[1], inner[2], inner[3], 1)
	if skin.CreateMaskTexture and disc.AddMaskTexture then
		local mask = skin:CreateMaskTexture()
		mask:SetTexture("Interface\\CharacterFrame\\TempPortraitAlphaMask", "CLAMPTOBLACKADDITIVE", "CLAMPTOBLACKADDITIVE")
		mask:SetAllPoints(disc)
		disc:AddMaskTexture(mask)
	end
	-- with the 3D Portrait off, the book stands in the ring (the picture
	-- shows its own emblem in the square)
	local emblem = skin:CreateTexture(nil, "ARTWORK")
	emblem:SetSize(dress.portraitSize * 0.8, dress.portraitSize * 0.8)
	emblem:SetPoint("CENTER", frame, "LEFT", L.ringX, 0)
	emblem:SetTexture(TexturePath("Book"))
	emblem:SetTexCoord(8 / 256, 248 / 256, 8 / 256, 248 / 256)
	dress.emblem = emblem
	local holder = CreateFrame("Frame", nil, frame)
	holder:EnableMouse(false)
	holder:SetAllPoints(frame)
	holder:SetFrameLevel(frame.portrait.border:GetFrameLevel() + 1)
	local ring = Kit:Texture(holder, "window/portrait_ring", "ARTWORK", 0, rscale)
	ring:SetPoint("CENTER", frame, "LEFT", L.ringX, 0)
	dress.ring = ring
	dress.parts[#dress.parts + 1] = holder

	-- the speaker's name on a title plate riding the top rail over the
	-- parchment, in the kit's title face, as every kit window's title (the
	-- plate is the windows' TitleBar piece, the red plate with rune caps);
	-- on the plate it keeps the font's own colour (the ink rule: text on a
	-- plate is not inked)
	local plate = Kit:Strip(frame, "tabs/top", { state = "open" })
	local yoff = plate:FitBox(L.plateBox) or 0
	local railMid = Kit.RailInset and Kit:RailInset(Kit.framePrefix .. "_t", "t") or 0
	plate:ClearAllPoints()
	plate:SetPoint("LEFT", frame, "TOPLEFT", L.plateL, -railMid + yoff)
	plate:SetPoint("RIGHT", frame, "TOPRIGHT", -L.plateR, -railMid + yoff)
	plate:SetHeight(plate.height)
	plate:FitCaps(FRAME_W - L.plateL - L.plateR)
	local name = plate:CreateFontString(nil, "OVERLAY", "GameFontNormal")
	-- centred on the plate's painted box (lower in its canvas than the
	-- middle), clear of the caps' gems
	name:SetPoint("LEFT", plate, "LEFT", (plate.wl or 0) * 0.6, -yoff)
	name:SetPoint("RIGHT", plate, "RIGHT", -(plate.wr or 0) * 0.6, -yoff)
	name:SetJustifyH("CENTER")
	name:SetWordWrap(false)
	if Kit.TitleFont then
		pcall(Kit.TitleFont, Kit, name, true)
	end
	dress.plate, dress.plateName = plate, name
	dress.parts[#dress.parts + 1] = plate

	-- where the first line hangs from in the kit: the container's top
	local head = CreateFrame("Frame", nil, frame.container)
	head:SetPoint("TOPLEFT")
	head:SetSize(1, 1)
	dress.head = head

	-- stop and skip in the kit's glyphs, following the button's hover and
	-- press (Kit:StateTexture); shown by stop:Refresh
	local stop = frame.container.stop
	dress.stopX = Kit:StateTexture(stop, "window/close")
	dress.skip = Kit:StateTexture(stop, "buttons/arrow_right")
	dress.stopX:Hide()
	dress.skip:Hide()

	for _, part in ipairs(dress.parts) do
		part:Hide()
	end
	return dress
end

-- The parchment and the stone laid again at the UI's one background density
-- (a new overlay scale, the dress just shown)
function Overlay:RetileDress()
	local dress = self.kitOn and self.dress
	if not dress then
		return
	end
	local Kit = MelloUI.Kit
	if Kit.RetileBackgrounds then
		Kit:RetileBackgrounds()
	end
	self:FitEdge()
end

-- the parchment's painted edge fitted to the paper's size
function Overlay:FitEdge()
	local dress = self.kitOn and self.dress
	if dress and dress.edge then
		local ok, w, h = pcall(dress.paper.GetSize, dress.paper)
		if ok and w and h and not IsSecret(w) and not IsSecret(h) and w > 0 and h > 0 then
			dress.edge:Fit(w, h)
		end
	end
end

-- Dress the window for the reskin's state: the kit's pieces while it is on,
-- the picture while it is off. Returns true when the dress changed.
function Overlay:Dress()
	local frame = self.frame
	if not frame then
		return false
	end
	local Kit = ReskinKit()
	if Kit and self.dress == nil then
		local building = { parts = {} }
		local ok, dress = pcall(self.BuildDress, self, Kit, building)
		-- false: tried and failed, the picture stays (and whatever was made
		-- before the failure is put away)
		self.dress = (ok and dress) or false
		if not self.dress then
			for _, part in ipairs(building.parts) do
				part:Hide()
			end
		end
	end
	local on = (Kit and self.dress) and true or false
	if on == (self.kitOn or false) then
		return false
	end
	self.kitOn = on
	local dress = self.dress
	for _, part in ipairs(frame.artParts or {}) do
		part:SetShown(not on)
	end
	if dress then
		for _, part in ipairs(dress.parts) do
			part:SetShown(on)
		end
	end
	local portrait, container = frame.portrait, frame.container
	local stop = container.stop
	portrait:ClearAllPoints()
	container:ClearAllPoints()
	stop:ClearAllPoints()
	if on then
		-- the model in the ring's opening; the lines from the parchment's
		-- top, a little lower for the plate; stop beside the padlock
		portrait:SetPoint("CENTER", frame, "LEFT", KIT_LAYOUT.ringX, 0)
		portrait:SetSize(dress.portraitSize, dress.portraitSize)
		container:SetPoint("LEFT", frame, "LEFT", PARCHMENT_LEFT, -4)
		container.head = dress.head
		container.name:Hide()
		stop:SetPoint("RIGHT", frame.lock, "LEFT", -2, 0)
		stop:SetSize(KIT_LAYOUT.stop[1], KIT_LAYOUT.stop[2])
	else
		-- as Create lays it out for the picture
		portrait:SetPoint("TOPLEFT", PORTRAIT_X, -PORTRAIT_Y)
		portrait:SetSize(PORTRAIT_SIZE, PORTRAIT_SIZE)
		container:SetPoint("LEFT", frame, "LEFT", PARCHMENT_LEFT, -1)
		container.head = container.name
		container.name:Show()
		stop:SetPoint("BOTTOMLEFT", container.name, "RIGHT", -6, 0)
		stop:SetSize(32, 32)
	end
	container.subtitle:SetTextColor(unpack(self:Ink().subtitle))
	stop:Refresh()
	self:RetileDress()
	return true
end

-- Apply the overlay settings (portrait, lock, scale, position).
function Overlay:Apply()
	local frame = self.frame
	if not frame then
		return
	end
	self:Dress()
	if frame.lock then
		frame.lock:Refresh()
	end
	FollowPadlock()
	-- without the model the art's own emblem shows in the square (the book
	-- in the ring in the kit)
	frame.portrait:SetShown(M.db.overlayPortrait and true or false)
	if self.dress then
		self.dress.emblem:SetShown(not M.db.overlayPortrait)
	end
	frame.portraitLine:Hide()
	frame.miniPause:Hide()
	-- a new scale: the stone and the parchment repeat at the same density
	-- on the screen, never a bigger copy -- those in the overlay, laid again
	-- only when its scale really changed (audit, 2026-09-24: each Apply laid
	-- every background in the UI)
	local scale, Kit = tonumber(M.db.overlayScale) or 1, MelloUI.Kit
	if self.kitOn and self.dress and Kit.SetFrameScale then
		Kit:SetFrameScale(frame, scale)
		self:FitEdge()
	else
		frame:SetScale(scale)
		self:RetileDress()
	end
	self:RestorePosition()
	self:Update()
end

-- Split a line into pages that fit the subtitle's lines, sentence by
-- sentence (a single too-long sentence is split on words).
local function BuildPages(fs, text)
	if not fs.IsTruncated then
		return { text }
	end
	local function Fits(candidate)
		fs:SetText(candidate)
		return not fs:IsTruncated()
	end
	local function Pack(pieces)
		local pages, page = {}, ""
		for _, piece in ipairs(pieces) do
			local candidate = page == "" and piece or (page .. " " .. piece)
			if page ~= "" and not Fits(candidate) then
				pages[#pages + 1] = page
				page = piece
			else
				page = candidate
			end
		end
		if page ~= "" then
			pages[#pages + 1] = page
		end
		return pages
	end
	local sentences = {}
	for raw in text:gmatch("%s*([^%.!%?]+[%.!%?]*)") do
		local sentence = raw:gsub("^%s+", ""):gsub("%s+$", "")
		if sentence ~= "" then
			sentences[#sentences + 1] = sentence
		end
	end
	local pages = {}
	for _, page in ipairs(Pack(sentences)) do
		if Fits(page) then
			pages[#pages + 1] = page
		else
			local words = {}
			for word in page:gmatch("%S+") do
				words[#words + 1] = word
			end
			for _, part in ipairs(Pack(words)) do
				pages[#pages + 1] = part
			end
		end
	end
	return #pages > 0 and pages or { text }
end

-- How long a page takes to SAY, in letters: its own letters plus the pauses
-- the voice makes at its punctuation -- about half a second at a full stop,
-- a quarter at a comma, which at a speaking pace of some 14 letters a second
-- are 7 and 3 letters (user, 2026-09-23: "go ahead with the subtitle
-- pacing"). A page ending a sentence carries that sentence's pause, so the
-- next page comes up when the voice starts it again, not during the pause.
local STOP_PAUSE, COMMA_PAUSE = 7, 3

local function SpokenWeight(text)
	local _, stops = text:gsub("[%.!%?]+", "")
	local _, commas = text:gsub("[,;:]", "")
	return #text + stops * STOP_PAUSE + commas * COMMA_PAUSE
end

-- Which page the playback is on: the share of the clip played so far against
-- the pages' spoken weights. The clip's own length where it is known (a
-- recorded line), else the estimate the text-to-speech line was timed by.
local function SubtitlePage(entry)
	local pages = entry.pages
	if not pages or #pages <= 1 then
		return 1
	end
	if not entry.pageWeights then
		local weights, total = {}, 0
		for i, page in ipairs(pages) do
			weights[i] = SpokenWeight(page)
			total = total + weights[i]
		end
		entry.pageWeights, entry.pageTotal = weights, total
	end
	local length = entry.length or entry.expected
	local progress = 0
	if length and length > 0 and entry.startedAt and not paused then
		progress = (GetTime() - entry.startedAt) / length
	end
	local at, index = 0, 1
	for i, weight in ipairs(entry.pageWeights) do
		if progress >= at / entry.pageTotal then
			index = i
		end
		at = at + weight
	end
	return math.min(index, #pages)
end
Overlay.SubtitlePage = SubtitlePage

function Overlay:Update()
	local frame = self.frame
	if not frame then
		return
	end
	local visible = M.db.overlay and M.isEnabled and (current ~= nil or #queue > 0)
	frame:SetShown(visible)
	if not visible then
		return
	end
	if self.mover == nil then
		RegisterOverlayMover(frame)
	end
	frame.portrait.pause:Update()
	frame.miniPause:Update()
	self:ConfigurePortrait(current or queue[1])

	local container = frame.container
	container:SetHeight(frame:GetHeight())
	local head = current or queue[1]
	container.name:SetText(head and (head.name or "Unknown") or "")
	if self.dress then
		self.dress.plateName:SetText(head and (head.name or "Unknown") or "")
	end
	container.stop:Refresh()

	-- Lines: the current one first, then the queue.
	local shown = 0
	local function Place(entry)
		if shown >= MAX_LINES then
			return
		end
		shown = shown + 1
		local line = container.lines[shown] or self:CreateLine(shown)
		line.entry = entry
	end
	if current then
		Place(current)
	end
	for _, entry in ipairs(queue) do
		Place(entry)
	end
	for i = shown + 1, #container.lines do
		container.lines[i].entry = nil
	end

	-- the padlock sits at the right edge (in the kit the stop button beside it)
	local width = PARCHMENT_RIGHT - PARCHMENT_LEFT - 32 - (self.kitOn and KIT_LAYOUT.stopW or 0)
	container:SetWidth(width)
	container.name:SetWidth(0)
	container.name:SetWidth(math.min(width - 26, container.name:GetStringWidth() + 1))
	for _, line in ipairs(container.lines) do
		line:Refresh()
	end

	-- Optional subtitle with the text being read, under the lines.
	local last = container.lines[shown] or container.head or container.name
	if M.db.overlaySubtitles and current and not current.secret then
		container.subtitle:ClearAllPoints()
		container.subtitle:SetPoint("TOPLEFT", last, "BOTTOMLEFT", 0, -6)
		container.subtitle:SetWidth(width)
		if not current.pages or current.pagesWidth ~= width then
			current.pages = BuildPages(container.subtitle, current.text)
			current.pagesWidth = width
			current.pageWeights = nil
		end
		current.page = SubtitlePage(current)
		container.subtitle:SetText(current.pages[current.page] or current.text)
		container.subtitle:Show()
		-- a new line or a new page fades in; the same page redrawn stays put
		if container.subtitle.shownEntry ~= current or container.subtitle.shownPage ~= current.page then
			container.subtitle.shownEntry, container.subtitle.shownPage = current, current.page
			container.subtitle.fade:Stop()
			-- Reduce Motion: the page is simply there (the group ends at its
			-- final alpha, 1)
			if MelloUI.Anim then
				MelloUI.Anim:PlayGroup(container.subtitle.fade)
			else
				container.subtitle.fade:Play()
			end
		end
		last = container.subtitle
	else
		container.subtitle:Hide()
	end

	-- Centre the content vertically.
	local top = (container.head or container.name):GetTop()
	local bottom = last:GetBottom()
	if top and bottom then
		container:SetHeight(math.max(20, top - bottom))
	end
end

--------------------------------------------------------------------------------
-- Dialog events
--------------------------------------------------------------------------------

local function PlainString(value)
	if type(value) == "string" and not IsSecret(value) then
		return value
	end
	return nil
end

local function QuestTitle()
	if GetTitleText then
		local ok, title = pcall(GetTitleText)
		if ok then
			return PlainString(title)
		end
	end
	return nil
end

local function GossipText()
	if C_GossipInfo and C_GossipInfo.GetText then
		local ok, text = pcall(C_GossipInfo.GetText)
		if ok then
			return text
		end
	end
	if GetGossipText then
		return GetGossipText()
	end
end

--------------------------------------------------------------------------------
-- Quest panels: read once the client has filled them in
--
-- QUEST_DETAIL / QUEST_PROGRESS / QUEST_COMPLETE fire synchronously, and on
-- the current Classic-line clients GetQuestID() can still answer 0, or the
-- previous quest's globals can still be in place, at that moment: the line
-- lost its recording or the wrong quest was read. The read is put off to
-- the next frame and retried a few times until the ID, title and text are
-- there, keyed so the same panel is not read twice when the event repeats.
--------------------------------------------------------------------------------

local QUEST_PANELS = { accept = "QuestFrameDetailPanel", progress = "QuestFrameProgressPanel", complete = "QuestFrameRewardPanel" }
local QUEST_TEXT = {
	accept = function() return GetQuestText and GetQuestText() or nil end,
	progress = function() return GetProgressText and GetProgressText() or nil end,
	complete = function() return GetRewardText and GetRewardText() or nil end,
}
local READ_TRIES, READ_STEP = 5, 0.1
local lastRead = { key = nil, at = 0 }
local readSerial = 0

local function ClientQuestID()
	if not GetQuestID then
		return nil
	end
	local ok, id = pcall(GetQuestID)
	id = ok and PlainNumber(id) or nil
	return id and id > 0 and id or nil
end

local function QuestPanelShown(kind)
	local panel = _G[QUEST_PANELS[kind]]
	-- No such frame on this client: trust the event.
	return not panel or panel:IsShown()
end

local function ReadQuestPanel(kind, serial, attempt)
	if serial ~= readSerial or not M.isEnabled or not QuestPanelShown(kind) then
		return
	end
	local questID = ClientQuestID()
	local title = QuestTitle()
	local text = QUEST_TEXT[kind]()
	local plain = PlainString(text)
	local ready = questID ~= nil and title ~= nil and (IsSecret(text) or (plain ~= nil and plain ~= ""))
	if not ready and attempt < READ_TRIES then
		C_Timer.After(READ_STEP, function() ReadQuestPanel(kind, serial, attempt + 1) end)
		return
	end
	local key = kind .. ":" .. tostring(questID or 0) .. ":" .. tostring(title)
	if key == lastRead.key and GetTime() - lastRead.at < 5 then
		return
	end
	lastRead.key, lastRead.at = key, GetTime()
	Trace("%s %q: client quest ID %s after %d read(s)", kind, tostring(title), tostring(questID or "none"), attempt)
	local spoken = text
	if kind == "accept" and M.db.questObjectives and GetObjectiveText and plain then
		local objectives = GetObjectiveText()
		if type(objectives) == "string" and not IsSecret(objectives) and objectives ~= "" then
			spoken = plain .. " " .. objectives
		end
	end
	Enqueue(spoken, DescribeNPC(), kind, title, questID, text)
end

local function ScheduleQuestRead(kind)
	readSerial = readSerial + 1
	local serial = readSerial
	C_Timer.After(0, function() ReadQuestPanel(kind, serial, 1) end)
end

local handlers = {
	GOSSIP_SHOW = function()
		if M.db.gossip then
			Enqueue(GossipText(), DescribeNPC(), "gossip")
		end
	end,
	QUEST_GREETING = function()
		if M.db.gossip and GetGreetingText then
			Enqueue(GetGreetingText(), DescribeNPC(), "gossip")
		end
	end,
	QUEST_DETAIL = function()
		if M.db.questDetail then
			ScheduleQuestRead("accept")
		end
	end,
	QUEST_PROGRESS = function()
		if M.db.questProgress and GetProgressText then
			ScheduleQuestRead("progress")
		end
	end,
	QUEST_COMPLETE = function()
		if M.db.questComplete and GetRewardText then
			ScheduleQuestRead("complete")
		end
	end,
	GOSSIP_CLOSED = function()
		if M.db.stopOnClose then
			Stop()
		end
	end,
	QUEST_FINISHED = function()
		if M.db.stopOnClose then
			Stop()
		end
	end,
	PLAYER_TARGET_CHANGED = function()
		if M.db.stopOnMove and current then
			Stop()
		end
	end,
	VOICE_CHAT_TTS_VOICES_UPDATE = function()
		RefreshVoices()
	end,
	VOICE_CHAT_TTS_PLAYBACK_FINISHED = function()
		if current and not current.file and not paused then
			OnFinished(current)
		end
	end,
	VOICE_CHAT_TTS_PLAYBACK_FAILED = function()
		if not failedWarned then
			failedWarned = true
			MelloUI:Print("Voice Over: text-to-speech playback failed. Check that a voice is installed and selected.")
		end
		if current and not current.file then
			OnFinished(current)
		end
	end,
}

local eventFrame = CreateFrame("Frame")
Perf.SetScript(eventFrame, "OnEvent", function(_, event, ...)
	local handler = handlers[event]
	if handler then
		handler(...)
	end
end)

--------------------------------------------------------------------------------
-- Quest log read-aloud
--
-- A button on the quest log's details view reads the selected quest: the
-- description in the giver's voice (the recorded offer line when a pack has
-- it), then the objectives with their current counts.
--------------------------------------------------------------------------------

-- The quest's row in the Quest List data (row[9] the giver's name, row[21]
-- the giver's NPC ID), found by walking the rows when a quest is read. Reading
-- is a click, not a loop, so no table of every quest is kept for it: a
-- { name, npcID } per quest held about a megabyte for a lookup made once per
-- Read. A quest listed twice takes its later row.
local function GiverRow(questID)
	local data = MelloUI_QuestListData
	if type(data) ~= "table" or type(data.quests) ~= "table" then
		return nil
	end
	local found
	for _, row in ipairs(data.quests) do
		if row[1] == questID and row[9] ~= "" then
			found = row
		end
	end
	return found
end

local function GiverForQuest(questID)
	local row = GiverRow(questID)
	if not npcLookup then
		BuildLookup()
	end
	local npcID = row and (row[21] or 0) ~= 0 and row[21] or nil
	local name = row and row[9] or nil
	if not npcID and M.db.soundPacks then
		-- Not in the quest list data (or an item starts it): the pack's own
		-- quest -> NPC table knows the vanilla givers.
		LoadSoundPacks()
		for _, pack in ipairs(packs) do
			local byQuest = pack.data.NPCIDLookupByQuestID
			local id = byQuest and byQuest[questID]
			if type(id) == "number" then
				npcID = id
				local names = pack.data.NPCNameLookupByNPCID
				name = name or (names and names[id]) or nil
				break
			end
		end
	end
	local info = npcID and npcLookup[npcID] or nil
	local gender = info and info.gender or "n"
	return {
		id = npcID,
		name = name,
		race = info and info.race or nil,
		gender = gender,
		female = gender == "f",
		source = info and (info.override and "override" or "data") or "unknown",
		remote = true,
	}
end

local function SpeakableObjectives(questID, objectivesText, description)
	local parts = {}
	if type(objectivesText) == "string" and not IsSecret(objectivesText) and objectivesText ~= "" then
		-- The objectives paragraph repeats the description on some quests
		-- (the recording already said it); only read it when it adds something.
		local same = false
		if type(description) == "string" and not IsSecret(description) then
			local a, b = Normalise(objectivesText), Normalise(description)
			same = a == b or (a ~= "" and b:find(a, 1, true) ~= nil) or Similarity(objectivesText, description) > 0.6
		end
		if not same then
			parts[#parts + 1] = objectivesText
		end
	end
	if C_QuestLog and C_QuestLog.GetQuestObjectives then
		local ok, list = pcall(C_QuestLog.GetQuestObjectives, questID)
		if ok and type(list) == "table" then
			for _, objective in ipairs(list) do
				local text = objective and objective.text
				if type(text) == "string" and not IsSecret(text) and text ~= "" then
					-- "Goretusk Liver: 0/8" -> "Goretusk Liver, 0 of 8"
					text = text:gsub("%s*:%s*", ", "):gsub("(%d+)%s*/%s*(%d+)", "%1 of %2")
					if objective.finished then
						text = text .. ", done"
					end
					parts[#parts + 1] = text .. "."
				end
			end
		end
	end
	if #parts == 0 then
		return nil
	end
	return "Objectives. " .. table.concat(parts, " ")
end


local function ReadQuest(questID)
	if not questID or not HasTTS() then
		return false
	end
	local logIndex
	if C_QuestLog and C_QuestLog.GetLogIndexForQuestID then
		local ok, idx = pcall(C_QuestLog.GetLogIndexForQuestID, questID)
		logIndex = ok and PlainNumber(idx) or nil
	end
	if not logIndex or not GetQuestLogQuestText then
		return false
	end
	local ok, description, objectivesText = pcall(GetQuestLogQuestText, logIndex)
	if not ok then
		return false
	end
	local title
	if C_QuestLog and C_QuestLog.GetTitleForQuestID then
		local okT, t = pcall(C_QuestLog.GetTitleForQuestID, questID)
		title = okT and type(t) == "string" and not IsSecret(t) and t or nil
	end
	Stop()
	local npc = GiverForQuest(questID)
	local spoken = false
	if type(description) == "string" and not IsSecret(description) and description ~= "" then
		Enqueue(description, npc, "accept", title, questID)
		spoken = true
	end
	local objectives = M.db.questLogObjectives and SpeakableObjectives(questID, objectivesText, description) or nil
	if objectives then
		Enqueue(objectives, npc, "objectives", "Objectives" .. (title and (": " .. title) or ""), questID)
		spoken = true
	end
	return spoken
end

local readButton = nil

local function IsReadingLog()
	if current and current.questID and (current.kind == "accept" or current.kind == "objectives") and current.npc and current.npc.remote then
		return true
	end
	for _, entry in ipairs(queue) do
		if entry.npc and entry.npc.remote then
			return true
		end
	end
	return false
end

local function CreateReadButton()
	if readButton or not (QuestMapFrame and QuestMapFrame.DetailsFrame and QuestMapFrame.DetailsFrame.BackFrame) then
		return
	end
	local frame = QuestMapFrame.DetailsFrame.BackFrame
	readButton = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate")
	readButton:SetSize(72, 22)
	readButton:SetPoint("RIGHT", frame, "RIGHT", -11, 4)
	readButton:SetText("Read")
	Perf.SetScript(readButton, "OnClick", function()
		if IsReadingLog() then
			Stop()
			MelloUI:PlayUISound("option_off")
		else
			local questID = QuestMapFrame.DetailsFrame.questID
			if not ReadQuest(questID) then
				MelloUI:Print("Voice Over: nothing to read for this quest.")
			else
				MelloUI:PlayUISound("option_on")
			end
		end
	end)
	Perf.SetScript(readButton, "OnEnter", function(self)
		GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
		GameTooltip:SetText("Read aloud", 1, 1, 1)
		GameTooltip:AddLine("Reads the quest's description in the quest giver's voice, then the objectives with their progress.", nil, nil, nil, true)
		GameTooltip:Show()
	end)
	Perf.SetScript(readButton, "OnLeave", function() GameTooltip:Hide() end)
	local acc = 0
	Perf.SetScript(readButton, "OnUpdate", function(self, elapsed)
		acc = acc + elapsed
		if acc < 0.25 then
			return
		end
		acc = 0
		local reading = IsReadingLog()
		if reading ~= self.reading then
			self.reading = reading
			self:SetText(reading and "Stop" or "Read")
		end
	end)
end

local function ApplyReadButton()
	if M.isEnabled and M.db.questLog and HasTTS() then
		CreateReadButton()
	end
	if readButton then
		readButton:SetShown(M.isEnabled and M.db.questLog and true or false)
	end
end

--------------------------------------------------------------------------------
-- Slash command
--------------------------------------------------------------------------------

local TEST_LINES = {
	"Greetings, traveller. The road ahead is long, but I trust you will manage.",
	"You there! Yes, you. I have work for someone who can swing a blade.",
	"Ah, another adventurer. Stay a while and listen.",
}

local function GenderWord(gender)
	if gender == "f" then return "female" end
	if gender == "m" then return "male" end
	return "none"
end

SLASH_MELLOVOICEOVER1 = "/voiceover"
SLASH_MELLOVOICEOVER2 = "/vo"
SlashCmdList.MELLOVOICEOVER = function(msg)
	msg = (msg or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
	if msg == "stop" or msg == "" then
		Stop()
	elseif msg == "pause" then
		TogglePaused()
		MelloUI:Print(paused and "Voice Over paused." or "Voice Over resumed.")
	elseif msg == "skip" then
		if current then
			Skip(current)
		end
	elseif msg == "read" then
		local questID = C_QuestLog and C_QuestLog.GetSelectedQuest and PlainNumber(select(2, pcall(C_QuestLog.GetSelectedQuest)))
		if not questID or questID == 0 then
			MelloUI:Print("Select a quest in the quest log first.")
		elseif not ReadQuest(questID) then
			MelloUI:Print("Nothing to read for that quest.")
		end
	elseif msg == "reset" then
		Overlay:ResetPosition()
		MelloUI:Print("Overlay position reset.")
	elseif msg == "lines" then
		local store = Collected()
		local quests, questLines, newQuestLines, gossip, newGossip = 0, 0, 0, 0, 0
		for _, kinds in pairs(store.quests) do
			quests = quests + 1
			for _, rec in pairs(kinds) do
				questLines = questLines + 1
				if not rec.recorded then newQuestLines = newQuestLines + 1 end
			end
		end
		for _, texts in pairs(store.gossip) do
			for _, rec in pairs(texts) do
				gossip = gossip + 1
				if not rec.recorded then newGossip = newGossip + 1 end
			end
		end
		MelloUI:Print("Collected this session: %d quest lines from %d quests (%d without a recording), %d greetings (%d without).",
			questLines, quests, newQuestLines, gossip, newGossip)
		local shown = 0
		for _, texts in pairs(store.gossip) do
			for text, rec in pairs(texts) do
				if shown < 3 then
					shown = shown + 1
					print(string.format("   %s: %s%s", tostring(rec.npc), text:sub(1, 60), rec.recorded and " (recorded)" or ""))
				end
			end
		end
		for _, kinds in pairs(store.quests) do
			for kind, rec in pairs(kinds) do
				if shown < 6 then
					shown = shown + 1
					print(string.format("   %s, %s of %q%s", tostring(rec.npc), kind, tostring(rec.title), rec.recorded and " (recorded)" or ""))
				end
			end
		end
		print("   /reload saves them; take them out before the game fully restarts, which drops them.")
	elseif msg == "packs" then
		LoadSoundPacks()
		if #packs == 0 and not next(packErrors) then
			MelloUI:Print("No VoiceOver sound packs installed (looked for addons with X-VoiceOver-DataModule-Version).")
		end
		for _, pack in ipairs(packs) do
			local files = 0
			for _ in pairs(pack.data.SoundLengthLookupByFileName) do files = files + 1 end
			MelloUI:Print("Pack %s: %d recorded lines (priority %d).", pack.name, files, pack.priority)
		end
		for name, err in pairs(packErrors) do
			MelloUI:Print("Pack %s could not be loaded: %s", name, err)
		end
		if current then
			print("   current line: " .. (current.file and ("recorded (" .. current.file .. ")") or "text-to-speech"))
		end
		for _, line in ipairs(lookupTrace) do
			print("   " .. line)
		end
	elseif msg == "portrait" then
		local frame = Overlay.frame
		local model = frame and frame.portrait and frame.portrait.model
		if not model then
			MelloUI:Print("Overlay not created yet.")
			return
		end
		local function Try(name, ...)
			local fn = model[name]
			if not fn then
				return name .. "=missing"
			end
			local ok, a, b = pcall(fn, model, ...)
			return string.format("%s=%s", name, ok and tostring(a) .. (b ~= nil and ("," .. tostring(b)) or "") or ("error: " .. tostring(a)))
		end
		MelloUI:Print("Portrait: creature %s, loaded %s, retries %s, shown %s, size %dx%d",
			tostring(model.creatureID), tostring(model.loaded), tostring(model.retries), tostring(model:IsShown()),
			model:GetWidth(), model:GetHeight())
		print("   " .. Try("GetModelFileID") .. "  " .. Try("GetModel") .. "  " .. Try("HasCustomCamera") .. "  " .. Try("GetModelScale"))
		print("   " .. Try("GetCameraPosition") .. "  " .. Try("GetPosition") .. "  " .. Try("GetModelAlpha"))
	elseif msg == "test" then
		if not M.isEnabled then
			MelloUI:Print("Voice Over is disabled. Enable it under /mello.")
			return
		end
		local npc = DescribeNPC(true)
		if npc then
			local profile = RACE_PROFILES[npc.race or ""] or DEFAULT_PROFILE
			MelloUI:Print("Reading as %s (%s, %s).", npc.name or ("NPC " .. npc.id), profile.label, GenderWord(npc.gender))
		else
			MelloUI:Print("No NPC targeted; reading with the male voice.")
		end
		Enqueue(TEST_LINES[math.random(#TEST_LINES)], npc, "gossip", "Test line")
	elseif msg == "voices" then
		RefreshVoices()
		if #voices == 0 then
			MelloUI:Print("No text-to-speech voices found.")
			return
		end
		MelloUI:Print("Installed voices (male pick: %s, female pick: %s):",
			tostring(voiceByID[PickVoice(nil, false) or -1] or "none"), tostring(voiceByID[PickVoice(nil, true) or -1] or "none"))
		for _, voice in ipairs(voices) do
			print(string.format("   %d  -  %s", voice.voiceID, voice.name))
		end
	elseif msg == "npc" then
		local npc = DescribeNPC(true)
		if not npc then
			MelloUI:Print("Target or talk to an NPC first.")
			return
		end
		local pitch, rate, profile = VoiceShape(npc.race)
		local voiceID = PickVoice(npc.race, npc.female)
		MelloUI:Print("%s  (NPC ID %d)", npc.name or "?", npc.id)
		print(string.format("   race: %s (%s)   gender: %s   source: %s",
			npc.race or "unknown", profile.label, GenderWord(npc.gender), npc.source))
		print(string.format("   voice: %s   pitch: %+d   speed: %+d", tostring(voiceByID[voiceID or -1] or "none"), pitch, rate))
		if npc.source == "unknown" then
			print(string.format('   Not in the data. Add to Media\\NPCVoiceOverrides.lua:  [%d] = { race = "human", gender = "%s" },',
				npc.id, npc.female and "f" or "m"))
		end
	else
		MelloUI:Print("/vo stop | pause | skip | read | test | voices | npc | packs | lines | reset | portrait")
	end
end

--------------------------------------------------------------------------------
-- Module lifecycle
--------------------------------------------------------------------------------

local EVENTS = {
	"GOSSIP_SHOW", "GOSSIP_CLOSED",
	"QUEST_GREETING", "QUEST_DETAIL", "QUEST_PROGRESS", "QUEST_COMPLETE", "QUEST_FINISHED",
	"PLAYER_TARGET_CHANGED",
	"VOICE_CHAT_TTS_VOICES_UPDATE", "VOICE_CHAT_TTS_PLAYBACK_FINISHED", "VOICE_CHAT_TTS_PLAYBACK_FAILED",
}

-- The overlay's look switched (UI Modifications' Painted kit reskin, or the
-- module itself, or a profile): it changes dress at once, not at the next
-- line. Told by the bus's 'look:voiceover' on the frame after the switch
-- (audit, 2026-09-24, ranks 1 and 5: it hooked NotifySettingChanged and
-- SetModuleEnabled, both run for every setting and module and never let
-- go; the kit's look pass listens to those and tells only a real change).
-- The Kit Colours need nothing here: every kit piece is re-pointed by
-- Kit:SetKitColours.
MelloUI:On("look:voiceover", function()
	if M.isEnabled and Overlay.frame and Overlay:Dress() then
		Overlay:Update()
	end
end, "Voice Over overlay")

function M:OnInit(db)
	self.db = db
	RefreshVoices()
end

function M:OnEnable(db)
	self.db = db
	-- Record Dialog Lines went off by default (user, 2026-09-24): every
	-- install had it on from the old default, so switch it off once; a
	-- player who wants it turns it back on and it stays
	if not db.collectLinesOffOnce then
		db.collectLinesOffOnce = true
		db.collectLines = false
	end
	RefreshVoices()
	npcLookup = nil
	if not HasTTS() then
		MelloUI:Print("Voice Over: this client has no text-to-speech API; the module will do nothing.")
		return
	end
	Overlay:Create()
	Overlay:Apply()
	ApplyReadButton()
	for _, event in ipairs(EVENTS) do
		pcall(eventFrame.RegisterEvent, eventFrame, event)
	end
	if db.collectLines then
		-- Create the store now so the saved file shows an empty table (the
		-- collector is running) rather than nothing at all.
		Collected()
	end
	if db.soundPacks then
		-- The packs' lookup tables are a few megabytes of Lua; load them a
		-- moment after login rather than inside the first dialog.
		C_Timer.After(3, function()
			if M.isEnabled and M.db.soundPacks then
				LoadSoundPacks()
			end
		end)
	end
end

function M:OnDisable()
	for _, event in ipairs(EVENTS) do
		pcall(eventFrame.UnregisterEvent, eventFrame, event)
	end
	Stop()
	if Overlay.frame then
		Overlay.frame:Hide()
	end
	if readButton then
		readButton:Hide()
	end
end

function M:OnSettingChanged(key, value, db)
	self.db = db
	if key == "maleVoice" or key == "femaleVoice" then
		-- Let the user hear the choice straight away.
		local female = key == "femaleVoice"
		SpeakSample(female and "This is the voice used for female characters." or "This is the voice used for male characters.", { female = female })
	elseif key:match("^voice_") then
		local groupKey = key:sub(7)
		for _, group in ipairs(RACE_GROUPS) do
			if group.key == groupKey then
				local race = group.races and next(group.races) or "other"
				SpeakSample("This is the voice used for " .. group.name:lower() .. ".", { race = race, female = false })
			end
		end
	elseif key:match("^overlay") then
		Overlay:Apply()
	elseif key == "questLog" then
		ApplyReadButton()
	end
end

MelloUI:Profile("VoiceOver", "dialog events", eventFrame)
MelloUI:Profile("VoiceOver", "sound pack load", LoadSoundPacks)
MelloUI:Profile("VoiceOver", "line lookup + queue", Enqueue)
